const DATA=[{"id": "v1n01", "vol": 1, "title": "中国社会各阶级的分析", "dateRaw": "（一九二五年十二月一日）", "y": 1925, "m": 12, "d": 1, "place": "广东广州", "lat": 23.1291, "lng": 113.2644, "era": "大革命时期", "why": "针对党内以陈独秀为代表的右倾（只注意同国民党合作、忘记农民）和以张国焘为代表的'左'倾（只注意工人运动、同样忘记农民）两种倾向，回答'谁是我们的敌人、谁是我们的朋友'这一革命首要问题，指出农民是无产阶级最广大最忠实的同盟军。", "event": "国共合作与国民革命", "links": ["湖南农民运动考察报告", "中国的红色政权为什么能够存在？", "星星之火，可以燎原"], "nChars": 6748, "startPage": 3}, {"id": "v1n02", "vol": 1, "title": "湖南农民运动考察报告", "dateRaw": "（一九二七年三月）", "y": 1927, "m": 3, "d": 1, "place": "湖南长沙", "lat": 28.2282, "lng": 112.9388, "era": "大革命时期", "why": "为答复党内外对农民革命斗争的责难而写。毛泽东经32天实地考察湖南五县农民运动，反驳以陈独秀为代表的右倾机会主义者不敢支持农民斗争的错误主张。", "event": "北伐战争与湖南农民运动兴起", "links": ["中国社会各阶级的分析", "国民革命与农民运动"], "nChars": 20966, "startPage": 10}, {"id": "v1n03", "vol": 1, "title": "中国的红色政权为什么能够存在？", "dateRaw": "（一九二八年十月五日）", "y": 1928, "m": 10, "d": 5, "place": "江西井冈山", "lat": 26.58, "lng": 114.16, "era": "土地革命战争时期", "why": "大革命失败后，党内和边界部分同志对井冈山红色政权能否长期存在存在疑虑和悲观情绪；毛泽东为中共湘赣边界第二次代表大会写决议，系统论证红色政权存在的原因和条件，回答'红旗到底打得多久'的疑问。", "event": "井冈山斗争", "links": ["井冈山的斗争", "星星之火，可以燎原", "中国社会各阶级的分析"], "nChars": 6687, "startPage": 31}, {"id": "v1n04", "vol": 1, "title": "井冈山的斗争", "dateRaw": "（一九二八年十一月二十五日）", "y": 1928, "m": 11, "d": 25, "place": "江西井冈山", "lat": 26.58, "lng": 114.16, "era": "土地革命战争时期", "why": "1928年11月25日毛泽东以红四军前委书记身份写给中共中央的书面报告，总结井冈山根据地一年来工农武装割据的经验教训，特别是检讨八月失败的错误，阐明红色政权能够存在和发展的条件与策略。", "event": "井冈山斗争", "links": ["中国的红色政权为什么能够存在？", "星星之火，可以燎原", "关于纠正党内的错误思想"], "nChars": 18589, "startPage": 38}, {"id": "v1n05", "vol": 1, "title": "关于纠正党内的错误思想", "dateRaw": "（一九二九年十二月）", "y": 1929, "m": 12, "d": 1, "place": "福建上杭县古田", "lat": 25.117, "lng": 116.783, "era": "土地革命战争时期", "why": "红四军党内因农民和小资产阶级成分占多数而存在单纯军事观点、极端民主化等各种非无产阶级思想，严重妨碍执行党的正确路线；毛泽东根据中央九月来信精神，为红四军第九次代表大会（古田会议）起草决议，总结建军经验，肃清旧式军队影响，确立党对军队绝对领导和政治工作的基本原则。", "event": "古田会议", "links": ["中国的红色政权为什么能够存在？", "井冈山的斗争", "星星之火，可以燎原"], "nChars": 6659, "startPage": 56}, {"id": "v1n06", "vol": 1, "title": "星星之火，可以燎原", "dateRaw": "（一九三○年一月五日）", "y": 1930, "m": 1, "d": 5, "place": "福建上杭县古田", "lat": 25.19, "lng": 116.75, "era": "土地革命战争时期", "why": "为答复林彪及党内部分同志对红军前途和革命形势的悲观估计而写，批评单纯流动游击、不愿建立巩固红色政权的思想，阐明以农村红色政权促进全国革命高潮的道路。", "event": "古田会议后的赣南闽西斗争", "links": ["中国的红色政权为什么能够存在？", "井冈山的斗争", "关于纠正党内的错误思想"], "nChars": 8300, "startPage": 64}, {"id": "v1n07", "vol": 1, "title": "反对本本主义", "dateRaw": "（一九三○年五月）", "y": 1930, "m": 5, "d": 1, "place": "江西寻乌", "lat": 24.915, "lng": 115.646, "era": "土地革命战争时期", "why": "为反对当时红军和党内把马克思主义教条化、把共产国际决议和苏联经验神圣化的“本本主义”倾向而写，强调调查研究、从实际出发，提出‘没有调查，没有发言权’。", "event": "寻乌调查", "links": ["中国社会各阶级的分析", "湖南农民运动考察报告", "井冈山的斗争"], "nChars": 5135, "startPage": 72}, {"id": "v1n08", "vol": 1, "title": "必须注意经济工作", "dateRaw": "（一九三三年八月十二日）", "y": 1933, "m": 8, "d": 12, "place": "江西瑞金", "lat": 25.88, "lng": 116.03, "era": "土地革命战争时期", "why": "针对中央苏区部分干部认为战争环境中不能搞经济建设、把谈经济建设斥为'右倾'的错误观点，在南部十七县经济建设大会上阐明经济建设对保障革命战争和改善群众生活、巩固工农联盟的必要性。", "event": "中央苏区反第五次'围剿'", "links": ["我们的经济政策", "关心群众生活，注意工作方法", "必须学会做经济工作"], "nChars": 5299, "startPage": 78}, {"id": "v1n09", "vol": 1, "title": "怎样分析农村阶级", "dateRaw": "（一九三三年十月）", "y": 1933, "m": 10, "d": 1, "place": "江西瑞金", "lat": 25.885, "lng": 116.027, "era": "土地革命战争时期", "why": "为纠正在土地改革工作中划分阶级成分的偏向、正确解决土地问题而写，作为中央工农民主政府划分农村阶级成分的标准文件。", "event": "中央苏区土地改革", "links": ["井冈山的斗争", "中国社会各阶级的分析", "湖南农民运动考察报告"], "nChars": 1262, "startPage": 83}, {"id": "v1n10", "vol": 1, "title": "我们的经济政策", "dateRaw": "（一九三四年一月）", "y": 1934, "m": 1, "d": 1, "place": "江西瑞金", "lat": 25.885, "lng": 116.027, "era": "土地革命战争时期", "why": "这是毛泽东在第二次全国工农兵代表大会上报告的一部分，针对国民党对红色区域的经济封锁和军事'围剿'，系统阐述苏区经济政策，动员经济建设以供给战争并改良民众生活。", "event": "第二次全国工农兵代表大会", "links": ["必须注意经济工作", "关心群众生活，注意工作方法", "我们的经济政策"], "nChars": 3354, "startPage": 85}, {"id": "v1n11", "vol": 1, "title": "关心群众生活，注意工作方法", "dateRaw": "（一九三四年一月二十七日）", "y": 1934, "m": 1, "d": 27, "place": "江西瑞金", "lat": 25.885, "lng": 116.027, "era": "土地革命战争时期", "why": "这是毛泽东在第二次全国工农兵代表大会上所作结论的一部分，针对苏区部分干部只顾扩大红军、动员运输队而忽视群众切身利益和工作方法的问题，强调只有关心群众生活、改进工作方法才能动员群众支持革命战争。", "event": "第二次全国工农兵代表大会", "links": ["我们的经济政策", "必须注意经济工作", "才溪乡调查"], "nChars": 3748, "startPage": 89}, {"id": "v1n12", "vol": 1, "title": "论反对日本帝国主义的策略", "dateRaw": "（一九三五年十二月二十七日）", "y": 1935, "m": 12, "d": 27, "place": "陕北子长县瓦窑堡（今陕西子长市瓦窑堡镇）", "lat": 37.1426, "lng": 109.6719, "era": "土地革命战争时期", "why": "红军长征到达陕北后，中共中央召开瓦窑堡政治局会议确定建立抗日民族统一战线的策略；本报告是毛泽东在会后向党的活动分子传达和阐发这一决议，批评关门主义和急性病，论证与民族资产阶级联合抗日的可能性和党的领导作用。", "event": "瓦窑堡会议", "links": ["中国社会各阶级的分析", "星星之火，可以燎原", "论持久战"], "nChars": 21216, "startPage": 93}, {"id": "v1n13", "vol": 1, "title": "中国革命战争的战略问题", "dateRaw": "（一九三六年十二月）", "y": 1936, "m": 12, "d": 1, "place": "陕北保安（今陕西志丹县）", "lat": 36.78, "lng": 108.75, "era": "土地革命战争时期", "why": "为总结第二次国内革命战争的经验、在陕北红军大学作讲演而写，系统清算党内军事路线上以王明'左'倾错误为代表的错误军事路线，阐明中国革命战争的战略规律。", "event": "第二次国内革命战争总结、遵义会议", "links": ["《论反对日本帝国主义的策略》", "《中国革命和中国共产党》", "《战争和战略问题》"], "nChars": 49430, "startPage": 114}, {"id": "v1n14", "vol": 1, "title": "关于蒋介石声明的声明", "dateRaw": "（一九三六年十二月二十八日）", "y": 1936, "m": 12, "d": 28, "place": "陕北保安（今陕西志丹县）", "lat": 36.8, "lng": 108.8, "era": "土地革命战争时期", "why": "西安事变和平解决后，蒋介石于1936年12月26日发表《对张杨的训词》，内容含糊曲折。毛泽东撰此文回应，督促蒋介石兑现事变中允诺的停止内战、联合抗日的条件。", "event": "西安事变", "links": ["中国共产党在抗日时期的任务", "论反对日本帝国主义的策略", "为动员一切力量争取抗战胜利而斗争"], "nChars": 5317, "startPage": 163}, {"id": "v1n15", "vol": 1, "title": "中国共产党在抗日时期的任务", "dateRaw": "（一九三七年五月三日）", "y": 1937, "m": 5, "d": 3, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "1937年5月延安苏区代表会议上，中日民族矛盾上升为主要矛盾，毛泽东向全党阐明由国内战争向抗日民族统一战线转变的任务与方针，为即将到来的全民族抗战作政治准备。", "event": "中国共产党全国代表会议（1937年延安）", "links": ["目前形势和我们的任务", "论反对日本帝国主义的策略", "为争取千百万群众进入抗日民族统一战线而斗争"], "nChars": 14915, "startPage": 168}, {"id": "v1n16", "vol": 1, "title": "为争取千百万群众进入抗日民族统一战线而斗争", "dateRaw": "（一九三七年五月八日）", "y": 1937, "m": 5, "d": 8, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "土地革命战争时期", "why": "毛泽东在延安召开的中国共产党全国代表会议上作结论，针对部分同志对国内和平是否取得、民族矛盾与国内矛盾关系的怀疑，论证'巩固和平、争取民主、实现抗战'三位一体任务，为争取千百万群众进入抗日民族统一战线而写。", "event": "中国共产党全国代表会议（1937年延安）", "links": ["中国共产党在抗日时期的任务", "论反对日本帝国主义的策略", "目前形势和我们的任务"], "nChars": 6610, "startPage": 182}, {"id": "v1n17", "vol": 1, "title": "实践论", "dateRaw": "（一九三七年七月）", "y": 1937, "m": 7, "d": 1, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "为揭露党内教条主义和经验主义、特别是教条主义这些主观主义错误而写，总结1931-1934年教条主义使中国革命遭受极大损失的教训，从马克思主义认识论上阐明认识和实践的关系。曾在延安抗日军事政治大学以此作讲演。", "event": "延安抗大讲演", "links": ["矛盾论", "中国革命战争的战略问题", "反对本本主义"], "nChars": 11294, "startPage": 189}, {"id": "v1n18", "vol": 1, "title": "矛盾论", "dateRaw": "（一九三七年八月）", "y": 1937, "m": 8, "d": 1, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "继《实践论》之后在延安抗大讲演的哲学论文，为克服党内严重的教条主义思想（与德波林学派影响相关），从哲学上总结中国革命经验教训而写。", "event": "延安抗大讲演", "links": ["实践论", "中国革命战争的战略问题", "论反对日本帝国主义的策略"], "nChars": 27698, "startPage": 200}, {"id": "v2n01", "vol": 2, "title": "反对日本进攻的方针、办法和前途", "dateRaw": "（一九三七年七月二十三日）", "y": 1937, "m": 7, "d": 23, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "卢沟桥事变后全国抗战爆发，针对蒋介石集团动摇妥协倾向，为阐明共产党的坚决抗战方针、办法和前途而写，回应对日方针上的路线分歧。", "event": "卢沟桥事变", "links": ["为动员一切力量争取抗战胜利而斗争", "论持久战", "中国共产党在抗日时期的任务"], "nChars": 5099, "startPage": 228}, {"id": "v2n02", "vol": 2, "title": "为动员一切力量争取抗战胜利而斗争", "dateRaw": "（一九三七年八月二十五日）", "y": 1937, "m": 8, "d": 25, "place": "陕北洛川", "lat": 35.7637, "lng": 109.4342, "era": "抗日战争时期", "why": "卢沟桥事变后全国性抗战开始，但国民党仍存在妥协压制民众的消极政策。毛泽东为中共中央宣传部起草此提纲，经洛川会议通过，旨在动员一切力量、提出抗日救国十大纲领以争取抗战胜利。", "event": "洛川会议", "links": ["反对日本进攻的方针、办法和前途", "上海太原失陷以后抗日战争的形势和任务", "论持久战"], "nChars": 3373, "startPage": 234}, {"id": "v2n03", "vol": 2, "title": "反对自由主义", "dateRaw": "（一九三七年九月七日）", "y": 1937, "m": 9, "d": 7, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "抗战初期大批新党员涌入、党内小资产阶级思想滋长，毛泽东针对党内自由主义种种表现，为增强党的团结和纪律、开展积极思想斗争而写。", "event": "抗日战争爆发后党的建设", "links": ["中国共产党在民族战争中的地位", "整顿党的作风", "关于纠正党内的错误思想"], "nChars": 1460, "startPage": 239}, {"id": "v2n04", "vol": 2, "title": "国共合作成立后的迫切任务", "dateRaw": "（一九三七年九月二十九日）", "y": 1937, "m": 9, "d": 29, "place": "陕北延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "1937年9月国共两党正式实现第二次合作、八路军刚开赴抗日前线之际，针对国民党仍未颁布共同纲领、未开放民众运动等问题，为巩固和扩大抗日民族统一战线、动员全面抗战而写。", "event": "第二次国共合作成立", "links": ["中国共产党在抗日时期的任务", "为动员一切力量争取抗战胜利而斗争", "和英国记者贝特兰的谈话"], "nChars": 7034, "startPage": 241}, {"id": "v2n05", "vol": 2, "title": "和英国记者贝特兰的谈话", "dateRaw": "（一九三七年十月二十五日）", "y": 1937, "m": 10, "d": 25, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "全面抗战爆发三个多月后，毛接受英国记者贝特兰采访，向国内外阐述中共的全面全民族抗战路线、抗日民族统一战线政策和《抗日救国十大纲领》，批评单纯政府军队抗战的片面抗战路线，并介绍八路军的战略方针。", "event": "抗日战争全面爆发、国共第二次合作", "links": ["反对日本进攻的方针、办法和前途", "国共合作成立后的迫切任务", "论持久战"], "nChars": 8061, "startPage": 248}, {"id": "v2n06", "vol": 2, "title": "上海太原失陷以后抗日战争的形势和任务", "dateRaw": "（一九三七年十一月十二日）", "y": 1937, "m": 11, "d": 12, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "上海、太原失陷后，抗战形势发生重大变化，党内出现右倾机会主义倾向，毛泽东在延安党的活动分子会议上作此报告提纲，分析片面抗战向全面抗战过渡的形势，强调共产党在统一战线中的独立自主原则。", "event": "抗日战争初期、上海太原失陷、六届六中全会", "links": ["反对日本进攻的方针、办法和前途", "为动员一切力量争取抗战胜利而斗争", "论持久战"], "nChars": 9957, "startPage": 257}, {"id": "v2n07", "vol": 2, "title": "陕甘宁边区政府第八路军后方留守处布告", "dateRaw": "（一九三八年五月十五日）", "y": 1938, "m": 5, "d": 15, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "抗战初期国共合作成立不久，蒋介石集团阴谋破坏陕甘宁边区，强迫农民交还土地、废除债务变更、煽动破坏，毛泽东为边区政府和八路军后方留守处起草布告予以取缔，同时批评党内对蒋妥协的机会主义立场。", "event": "抗日民族统一战线建立", "links": ["中国共产党在民族战争中的地位", "统一战线中的独立自主问题", "和英国记者贝特兰的谈话"], "nChars": 1781, "startPage": 268}, {"id": "v2n08", "vol": 2, "title": "抗日游击战争的战略问题", "dateRaw": "（一九三八年五月）", "y": 1938, "m": 5, "d": 1, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "抗战初期党内党外许多人轻视游击战争的战略作用，把希望寄托于正规战争特别是国民党军队的作战；毛泽东为批驳这种观点、为八路军新四军指明抗日游击战争发展的正确道路而写。", "event": "抗日战争", "links": ["论持久战", "战争和战略问题", "中国革命战争的战略问题"], "nChars": 21432, "startPage": 270}, {"id": "v2n09", "vol": 2, "title": "论持久战", "dateRaw": "（一九三八年五月）", "y": 1938, "m": 5, "d": 1, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "针对当时流行的'亡国论'和'速胜论'两种错误观点，以及广大民众对抗战前途的疑问，毛泽东在延安抗日战争研究会上系统阐明中国抗战必经持久战、最后胜利属于中国的道理，为全国军民指明抗战的正确方针。", "event": "抗日战争一周年、延安抗日战争研究会讲演", "links": ["反对日本进攻的方针、办法和前途", "抗日游击战争的战略问题", "论新阶段"], "nChars": 53043, "startPage": 291}, {"id": "v2n10", "vol": 2, "title": "中国共产党在民族战争中的地位", "dateRaw": "（一九三八年十月十四日）", "y": 1938, "m": 10, "d": 14, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "这是毛泽东在中共六届六中全会所作政治报告《论新阶段》的一部分，为使全党明确并认真担负起中国共产党领导抗日战争的历史责任，回答共产党员如何认识自己、加强自己、团结自己的问题。", "event": "六届六中全会", "links": ["论新阶段", "统一战线中的独立自主问题", "战争和战略问题"], "nChars": 10791, "startPage": 341}, {"id": "v2n11", "vol": 2, "title": "统一战线中的独立自主问题", "dateRaw": "（一九三八年十一月五日）", "y": 1938, "m": 11, "d": 5, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "毛泽东在六届六中全会上作结论的一部分，针对党内（主要是陈绍禹/王明）在抗日民族统一战线中'一切经过统一战线'、放弃无产阶级领导权的右倾主张，强调统一战线中的独立自主原则。", "event": "六届六中全会", "links": ["论新阶段", "目前形势和我们的任务", "中国共产党在民族战争中的地位"], "nChars": 2504, "startPage": 352}, {"id": "v2n12", "vol": 2, "title": "战争和战略问题", "dateRaw": "（一九三八年十一月六日）", "y": 1938, "m": 11, "d": 6, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "这是毛泽东在六届六中全会（1938年9-11月于延安举行）上所作结论的一部分。针对党内以王明为代表的右倾机会主义否认统一战线中的独立自主、怀疑党在战争和战略问题上的方针，毛泽东从中国政治斗争历史阐明武装夺取政权和战争战略在中国革命中的首要地位，统一全党思想。", "event": "六届六中全会", "links": ["抗日游击战争的战略问题", "论持久战", "统一战线中的独立自主问题"], "nChars": 11469, "startPage": 355}, {"id": "v2n13", "vol": 2, "title": "五四运动", "dateRaw": "（一九三九年五月一日）", "y": 1939, "m": 5, "d": 1, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "为延安《解放》周刊纪念五四运动二十周年而作，通过总结中国资产阶级民主革命的历史进程，论证抗日战争是民主革命的新阶段，强调工人阶级领导和抗日民族统一战线的重要性。", "event": "五四运动二十周年纪念", "links": ["青年运动的方向", "中国革命和中国共产党", "新民主主义论"], "nChars": 1521, "startPage": 367}, {"id": "v2n14", "vol": 2, "title": "青年运动的方向", "dateRaw": "（一九三九年五月四日）", "y": 1939, "m": 5, "d": 4, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "在延安青年群众纪念五四运动二十周年大会上发表讲演，针对中国青年运动如何服务于反帝反封建革命、特别是抗日战争胜利的问题，为中国青年指明运动方向。", "event": "五四运动二十周年纪念", "links": ["五四运动", "新民主主义论", "中国革命和中国共产党"], "nChars": 6060, "startPage": 369}, {"id": "v2n15", "vol": 2, "title": "反对投降活动", "dateRaw": "（一九三九年六月三十日）", "y": 1939, "m": 6, "d": 30, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "为纪念抗日战争两周年而写。针对相持阶段到来后日本诱降、国际妥协空气和国内主和派（投降派）散布反共谣言、酝酿妥协投降的动向，揭露其欺骗宣传，号召巩固抗日民族统一战线、坚持抗战反对投降。", "event": "抗日战争两周年、国民党投降逆流", "links": ["论持久战", "和中央社、扫荡报、新民报三记者的谈话", "目前形势和党的任务"], "nChars": 3319, "startPage": 375}, {"id": "v2n16", "vol": 2, "title": "必须制裁反动派", "dateRaw": "（一九三九年八月一日）", "y": 1939, "m": 8, "d": 1, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "1939年6月12日国民党顽固派制造平江惨案，杀害新四军平江通讯处涂正坤、罗梓铭等抗日干部。毛泽东在延安追悼大会上发表演说，揭露反动派破坏团结抗战、准备投降的行径，要求制裁反动派、实现真正的统一。", "event": "平江惨案", "links": ["《和中央社、扫荡报、新民报三记者的谈话》", "《〈共产党人〉发刊词》"], "nChars": 2964, "startPage": 379}, {"id": "v2n17", "vol": 2, "title": "关于国际新形势对新华日报⑴记者的谈话", "dateRaw": "（一九三九年九月一日）", "y": 1939, "m": 9, "d": 1, "place": "陕西延安", "lat": 36.65, "lng": 109.49, "era": "抗日战争时期", "why": "苏德互不侵犯协定签订、英法苏谈判破裂并值德国进攻波兰之际，记者就国际局势提问。谈话旨在说明协定的政治意义，批判英法“不干涉”政策，并指出其对中国抗战与国内投降派、抗战派的影响。", "event": "苏德互不侵犯协定", "links": ["反对投降活动", "必须强调团结和进步"], "nChars": 4362, "startPage": 382}, {"id": "v2n18", "vol": 2, "title": "和中央社、扫荡报、新民报⑴三记者的谈话", "dateRaw": "（一九三九年九月十六日）", "y": 1939, "m": 9, "d": 16, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "1939年9月抗战进入相持阶段、国民党转向消极抗日并加强限共反共之际，毛泽东借回答中央社等三报记者提问，阐明对相持阶段到来的判断，呼吁实行民主宪政、坚持团结抗战并准备反攻。", "event": "抗日战争相持阶段到来", "links": ["和英国记者贝特兰的谈话", "《共产党人》发刊词", "新民主主义论"], "nChars": 3611, "startPage": 387}, {"id": "v2n19", "vol": 2, "title": "苏联利益和人类利益的一致", "dateRaw": "（一九三九年九月二十八日）", "y": 1939, "m": 9, "d": 28, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "苏德签订互不侵犯条约及欧战爆发后，国内一些人指责苏联促成大战、不维护和平。毛泽东应中苏文化协会之邀，撰文回应这些争议，论证苏联和平政策与人类利益的一致性，并阐述对欧洲大战和苏联对外政策的看法。", "event": "苏德互不侵犯条约签订、第二次世界大战爆发", "links": ["《和英国记者贝特兰的谈话》", "《论持久战》", "《新民主主义论》"], "nChars": 6174, "startPage": 391}, {"id": "v2n20", "vol": 2, "title": "《共产党人》发刊词", "dateRaw": "（一九三九年十月四日）", "y": 1939, "m": 10, "d": 4, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "为中共中央党内刊物《共产党人》创刊而写，阐明其任务是帮助建设一个全国范围的、广大群众性的、思想上政治上组织上完全巩固的布尔什维克化的党，以应对投降、分裂、倒退危险和新党员大量增加带来的建党问题。", "event": "抗日战争相持阶段国民党反共摩擦加剧", "links": ["《〈共产党人〉发刊词》关联统一战线与武装斗争论述，相关文章：《中国革命战争的战略问题》《论持久战》《〈农村调查〉的序言和跋》"], "nChars": 8744, "startPage": 397}, {"id": "v2n21", "vol": 2, "title": "目前形势和党的任务", "dateRaw": "（一九三九年十月十日）", "y": 1939, "m": 10, "d": 10, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "二战爆发、日军对华政策转为政治进攻为主并诱降国民党，投降危险增长，毛泽东为中共中央起草此决定，分析相持阶段到来的形势，向全党提出坚持抗战、团结、进步，准备反攻的任务。", "event": "第二次世界大战爆发、第一次长沙会战", "links": ["《论持久战》", "《和英国记者贝特兰的谈话》", "《大量吸收知识分子》"], "nChars": 1353, "startPage": 406}, {"id": "v2n22", "vol": 2, "title": "大量吸收知识分子", "dateRaw": "（一九三九年十二月一日）", "y": 1939, "m": 12, "d": 1, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "抗战进入相持阶段后，党内许多干部恐惧甚至排斥知识分子，影响抗战力量和统一战线的发展。毛泽东为中共中央起草此决定，纠正这一倾向，要求全党全军大量吸收知识分子参加革命。", "event": "抗日战争相持阶段", "links": ["《青年运动的方向", "《新民主主义论", "《文化工作中的统一战线"], "nChars": 1414, "startPage": 408}, {"id": "v2n23", "vol": 2, "title": "中国革命和中国共产党", "dateRaw": "（一九三九年十二月）", "y": 1939, "m": 12, "d": 1, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "抗战进入相持阶段，为向党员干部和群众系统进行中国革命基本理论教育，毛泽东与其他在延安的同志合作编写这一课本，阐明中国社会性质、革命对象、任务、动力和前途，初步提出新民主主义观点。", "event": "抗日战争（相持阶段延安干部理论教育）", "links": ["新民主主义论", "中国革命战争的战略问题", "论持久战"], "nChars": 22491, "startPage": 410}, {"id": "v2n24", "vol": 2, "title": "斯大林是中国人民的朋友", "dateRaw": "（一九三九年十二月二十日）", "y": 1939, "m": 12, "d": 20, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "为纪念斯大林六十岁生日而写，回应抗战时期中国急需国际援助的处境，批判口称同情中国的帝国主义者，申明只有苏联是中国真正的朋友，以驳斥挑拨中苏关系的言论。", "event": "斯大林六十寿辰", "links": ["《苏联利益和人类利益的一致》，《和英国记者贝特兰的谈话》，《中国共产党在民族战争中的地位》"], "nChars": 927, "startPage": 433}, {"id": "v2n25", "vol": 2, "title": "纪念白求恩", "dateRaw": "（一九三九年十二月二十一日）", "y": 1939, "m": 12, "d": 21, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "为悼念1939年11月在晋察冀边区以身殉职的加拿大援华医生白求恩而写，号召全体党员学习其国际主义与毫不利己专门利人的精神，批评党内自私自利、敷衍工作的现象。", "event": "白求恩殉职", "links": ["为人民服务", "愚公移山", "论持久战"], "nChars": 1368, "startPage": 435}, {"id": "v2n26", "vol": 2, "title": "新民主主义论", "dateRaw": "（一九四○年一月）", "y": 1940, "m": 1, "d": 1, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "针对抗战以来国内出现的妥协空气和反共声浪，回答'中国向何处去'的问题，系统阐述中国共产党关于新民主主义政治、经济、文化的纲领，为陕甘宁边区文化协会第一次代表大会而作。", "event": "陕甘宁边区文化协会第一次代表大会", "links": ["《中国革命和中国共产党》", "《〈共产党人〉发刊词》", "《论联合政府》"], "nChars": 32509, "startPage": 437}, {"id": "v2n27", "vol": 2, "title": "克服投降危险，力争时局好转", "dateRaw": "（一九四○年一月二十八日）", "y": 1940, "m": 1, "d": 28, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "1940年初国民党顽固派掀起反共投降逆流，汪精卫公开叛国，毛泽东为中共中央起草党内指示，分析时局的两种前途，要求全党既坚决反抗投降反共逆流，又发展统一战线，力争时局好转。", "event": "抗日战争相持阶段反共高潮", "links": ["《目前形势和党的任务》", "《〈共产党人〉发刊词》", "《新民主主义论》"], "nChars": 1908, "startPage": 469}, {"id": "v2n28", "vol": 2, "title": "团结一切抗日力量，反对反共顽固派", "dateRaw": "（一九四○年二月一日）", "y": 1940, "m": 2, "d": 1, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "1940年初汪精卫与日本签订卖国条约并筹建伪政权，国民党顽固派配合反共制造多起摩擦惨案，毛泽东在延安民众讨汪大会上发表讲演，声讨汪精卫、揭露顽固派反共行径，以团结一切抗日力量、坚持抗战团结进步的方针。", "event": "日汪卖国条约签订与第一次反共高潮", "links": ["《新民主主义论", "《目前形势和党的任务", "《和中央社、扫荡报、新民报三记者的谈话"], "nChars": 4165, "startPage": 471}, {"id": "v2n29", "vol": 2, "title": "向国民党的十点要求", "dateRaw": "（一九四○年二月一日）", "y": 1940, "m": 2, "d": 1, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "1940年2月1日延安民众举行讨汪大会，声讨汪精卫叛国投敌、订立卖国密约。毛泽东为大会起草通电，向国民党提出十点救国要求，旨在揭露假统一、反对投降分裂倒退，争取时局好转和抗战胜利。", "event": "延安民众讨汪大会", "links": ["目前形势和党的任务", "克服投降危险，力争时局好转", "团结一切抗日力量，反对反共顽固派"], "nChars": 3669, "startPage": 475}, {"id": "v2n30", "vol": 2, "title": "《中国工人》发刊词", "dateRaw": "（一九四○年二月七日）", "y": 1940, "m": 2, "d": 7, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "为中共中央职工运动委员会主办的《中国工人》月刊在延安创刊而写，向工人群众阐明抗战时期工人阶级团结自己、团结人民、反帝反封建以建立新民主主义中国的当前任务，并希望刊物办成教育工人、培养干部的学校。", "event": "抗日战争", "links": ["《〈共产党人〉发刊词》", "《新民主主义论》", "《中国革命和中国共产党》"], "nChars": 913, "startPage": 479}, {"id": "v2n31", "vol": 2, "title": "必须强调团结和进步", "dateRaw": "（一九四○年二月七日）", "y": 1940, "m": 2, "d": 7, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "为延安《新中华报》改版一周年纪念而写，针对国民党顽固派的投降、分裂、倒退倾向（汪精卫伪政府、反共磨擦、限制异党活动等），阐明抗战、团结、进步三位一体的方针，号召以团结和进步争取抗战胜利。", "event": "抗日战争相持阶段的反共磨擦与投降危机", "links": ["克服投降危险，力争时局好转", "团结一切抗日力量，反对反共顽固派", "陕甘宁边区政府、第八路军后方留守处布告"], "nChars": 1091, "startPage": 480}, {"id": "v2n32", "vol": 2, "title": "新民主主义的宪政", "dateRaw": "（一九四○年二月二十日）", "y": 1940, "m": 2, "d": 20, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "针对蒋介石假借'实行宪政'的欺骗宣传以及党内部分同志被迷惑的问题，毛泽东在延安各界宪政促进会成立大会上揭露其骗局，把宪政促进运动变为启发人民觉悟、向国民党要求民主自由的武器。", "event": "延安各界宪政促进会成立大会", "links": ["《新民主主义论", "《中国革命和中国共产党", "《抗日根据地的政权问题"], "nChars": 6448, "startPage": 482}, {"id": "v2n33", "vol": 2, "title": "抗日根据地的政权问题", "dateRaw": "（一九四○年三月六日）", "y": 1940, "m": 3, "d": 6, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "针对国民党反共顽固派极力反对中共在华北、华中建立抗日民主政权，以及党内存在的过左过右倾向（特别是忽视争取中等资产阶级和开明绅士的'左'倾），毛泽东为中共中央起草党内指示，阐明抗日根据地政权的统一战线性质和'三三制'原则。", "event": "抗日根据地'三三制'政权建设", "links": ["目前抗日统一战线中的策略问题", "《共产党人》发刊词", "新民主主义论"], "nChars": 1604, "startPage": 489}, {"id": "v2n34", "vol": 2, "title": "目前抗日统一战线中的策略问题", "dateRaw": "（一九四○年三月十一日）", "y": 1940, "m": 3, "d": 11, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "针对1939年底以来国民党顽固派掀起反共高潮、统一战线面临分裂危险的形势，毛泽东在延安高级干部会议上作报告，阐明发展进步势力、争取中间势力、反对顽固势力的策略方针，纠正党内'左'右倾错误认识。", "event": "第一次反共高潮", "links": ["《中国共产党在民族战争中的地位》", "《〈共产党人〉发刊词》", "《论政策》"], "nChars": 5771, "startPage": 491}, {"id": "v2n35", "vol": 2, "title": "放手发展抗日力量，抵抗反共顽固派的进攻", "dateRaw": "（一九四○年五月四日）", "y": 1940, "m": 5, "d": 4, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "1940年国民党顽固派加紧防共限共反共，而东南局书记项英存在严重右倾观点，不敢放手在敌后发展力量。毛泽东为中共中央起草给东南局的指示，纠正右倾，要求独立自主扩大军队、建立根据地，准备抵抗反共顽固派的进攻。", "event": "皖南事变前夜的反共高潮", "links": ["目前抗日统一战线中的策略问题", "论政策", "统一战线中的独立自主问题"], "nChars": 4046, "startPage": 497}, {"id": "v2n36", "vol": 2, "title": "团结到底", "dateRaw": "（一九四○年七月五日）", "y": 1940, "m": 7, "d": 5, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "为延安《新中华报》纪念抗战三周年而作，配合党中央对时局宣言，号召抗战到底、团结到底，要求共产党员既反对投降派和反共逆流，又防止'左'右倾错误，坚持抗日民族统一战线。", "event": "抗日战争三周年纪念", "links": ["目前形势和党的任务", "新民主主义论", "共产党人发刊词"], "nChars": 1758, "startPage": 501}, {"id": "v2n37", "vol": 2, "title": "论政策", "dateRaw": "（一九四○年十二月二十五日）", "y": 1940, "m": 12, "d": 25, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "1940年底国民党掀起第二次反共高潮，党内许多干部仍沿用过左的土地革命时期政策，毛泽东为中共中央起草党内指示，系统阐明抗日民族统一战线中综合联合与斗争的各项具体政策。", "event": "第二次反共高潮", "links": ["目前形势和党的任务", "统一战线中的独立自主问题", "《共产党人》发刊词"], "nChars": 5401, "startPage": 503}, {"id": "v2n38", "vol": 2, "title": "为皖南事变发表的命令和谈话", "dateRaw": "（一九四一年一月二十日）", "y": 1941, "m": 1, "d": 20, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "1941年1月皖南事变爆发，国民党袭击奉令北移的新四军并取消其番号。毛泽东以中共中央革命军事委员会名义发布命令重建新四军军部，并通过发言人谈话揭露亲日派与国民党顽固派发动内战的阴谋，表明中共坚持抗战、反对分裂的严正立场。", "event": "皖南事变", "links": ["和中央社、扫荡报、新民报三记者的谈话", "目前抗日统一战线中的策略问题", "论政策"], "nChars": 3963, "startPage": 509}, {"id": "v2n39", "vol": 2, "title": "打退第二次反共高潮后的时局", "dateRaw": "（一九四一年三月十八日）", "y": 1941, "m": 3, "d": 18, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "皖南事变及第二次反共高潮被打退后，毛泽东为中共中央起草党内指示，分析时局走向缓和的趋势，总结有理、有利、有节的斗争策略，并告诫全党对国民党的压迫保持警惕。", "event": "皖南事变", "links": ["打退第二次反共高潮的总结（见《毛泽东选集》第二卷《关于打退第二次反共高潮的总结》）", "论政策", "目前抗日统一战线中的策略问题"], "nChars": 1867, "startPage": 514}, {"id": "v2n40", "vol": 2, "title": "关于打退第二次反共高潮的总结", "dateRaw": "（一九四一年五月八日）", "y": 1941, "m": 5, "d": 8, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "皖南事变引发的第二次反共高潮被击退后，党内部分同志对时局估计过左（误认为会是四一二、马日事变重演），毛泽东为中共中央起草党内指示，总结斗争经验教训，纠正错误认识，明确对国民党一打一拉的革命两面政策。", "event": "皖南事变", "links": ["《论政策》", "《打退第二次反共高潮后的时局》", "《目前抗日统一战线中的策略问题》"], "nChars": 3638, "startPage": 516}, {"id": "v3n01", "vol": 3, "title": "《农村调查》的序言和跋", "dateRaw": "（一九四一年三月十七日）", "y": 1941, "m": 3, "d": 17, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "为《农村调查》材料集出版作序，针对党内许多同志粗枝大叶、不了解下情的作风，号召全党用阶级分析方法开展调查研究，了解各阶级实际情况以实行抗日民族统一战线的农村政策。", "event": "延安整风（准备阶段）", "links": ["《反对本本主义》", "《〈共产党人〉发刊词》", "《改造我们的学习》"], "nChars": 3435, "startPage": 521}, {"id": "v3n02", "vol": 3, "title": "改造我们的学习", "dateRaw": "（一九四一年五月十九日）", "y": 1941, "m": 5, "d": 19, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "1941年抗战相持阶段，党内仍存在主观主义特别是教条主义的思想作风，毛泽东在延安干部会上作此报告，为整风运动作思想动员，号召全党把马克思列宁主义与中国革命实际相结合，改造学习方法和学习制度。", "event": "延安整风运动", "links": ["整顿党的作风", "反对党八股", "〈共产党人〉发刊词"], "nChars": 5406, "startPage": 525}, {"id": "v3n03", "vol": 3, "title": "揭破远东慕尼黑的阴谋", "dateRaw": "（一九四一年五月二十五日）", "y": 1941, "m": 5, "d": 25, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "针对1941年日美妥协、牺牲中国的'东方慕尼黑'阴谋及日本对蒋诱降、国民党散布反共谣言的局势，毛泽东为中共中央起草党内指示，要求全党揭穿和反对投降分裂阴谋，同时宣传八路军新四军抗战战绩，回击污蔑。", "event": "中条山战役（晋南战役）", "links": ["反对投降活动", "《共产党人》发刊词", "论政策"], "nChars": 746, "startPage": 531}, {"id": "v3n04", "vol": 3, "title": "关于反法西斯的国际统一战线", "dateRaw": "（一九四一年六月二十三日）", "y": 1941, "m": 6, "d": 23, "place": "陕北延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "1941年6月22日德国突然进攻苏联，苏德战争爆发。毛泽东为中共中央起草党内指示，回应这一事件，提出组织国际反法西斯统一战线，并明确党在中国坚持抗日民族统一战线、援助苏联的任务。", "event": "苏德战争爆发", "links": ["目前形势和党的任务", "中国共产党在民族战争中的地位", "论持久战"], "nChars": 400, "startPage": 532}, {"id": "v3n05", "vol": 3, "title": "在陕甘宁边区参议会的演说", "dateRaw": "（一九四一年十一月六日）", "y": 1941, "m": 11, "d": 6, "place": "陕甘宁边区延安（陕西延安）", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "1941年11月陕甘宁边区第二届参议会开幕，毛泽东发表演说，阐明共产党团结一切抗日党派、阶级，特别是照顾中间阶级利益，实行革命的三民主义（新民主主义）政策，以巩固边区抗日民主政权并回应对共产党政策的疑虑。", "event": "陕甘宁边区第二届参议会", "links": ["新民主主义论", "《共产党人》发刊词", "目前形势和我们的任务"], "nChars": 2263, "startPage": 533}, {"id": "v3n06", "vol": 3, "title": "整顿党的作风", "dateRaw": "（一九四二年二月一日）", "y": 1942, "m": 2, "d": 1, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "针对党内存在的主观主义、宗派主义、党八股三股歪风，毛泽东在中央党校开学典礼上作此演说，为延安整风运动确定任务，统一全党思想以战胜敌人。", "event": "延安整风运动", "links": ["改造我们的学习", "反对党八股", "〈共产党人〉发刊词"], "nChars": 11944, "startPage": 536}, {"id": "v3n07", "vol": 3, "title": "反对党八股", "dateRaw": "（一九四二年二月八日）", "y": 1942, "m": 2, "d": 8, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "1942年延安整风运动中，为清算主观主义和宗派主义的宣传工具——党八股，整顿文风而作，是毛泽东在延安干部会上的讲演。", "event": "延安整风运动", "links": ["改造我们的学习", "整顿党的作风", "在延安文艺座谈会上的讲话"], "nChars": 11335, "startPage": 548}, {"id": "v3n08", "vol": 3, "title": "在延安文艺座谈会上的讲话", "dateRaw": "（一九四二年五月）", "y": 1942, "m": 5, "d": 1, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "针对大批文艺工作者来到延安后与根据地群众结合不够、文艺界存在立场和认识分歧的状况，毛泽东召开文艺座谈会，阐明文艺为工农兵服务、为革命服务的方针，统一文艺队伍的思想。", "event": "延安文艺座谈会", "links": ["《新民主主义论》", "《反对党八股》", "《在陕甘宁边区参议会的演说》"], "nChars": 21134, "startPage": 560}, {"id": "v3n09", "vol": 3, "title": "一个极其重要的政策", "dateRaw": "（一九四二年九月七日）", "y": 1942, "m": 9, "d": 7, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "为延安《解放日报》撰写社论，针对部分根据地同志对精兵简政认识不足、执行不力的问题，阐明精兵简政是应对抗战最后阶段'黎明前的黑暗'极端物质困难、争取胜利的极其重要政策。", "event": "精兵简政", "links": ["抗日时期的经济问题和财政问题", "组织起来", "论联合政府"], "nChars": 2453, "startPage": 580}, {"id": "v3n10", "vol": 3, "title": "第二次世界大战的转折点", "dateRaw": "（一九四二年十月十二日）", "y": 1942, "m": 10, "d": 12, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "毛泽东为延安《解放日报》撰写社论，针对斯大林格勒战役中部分人仍被德军攻势迷惑、看不出法西斯即将溃败的形势，论述这一战役是苏德战争乃至世界反法西斯战争和人类历史的转折点，以鼓舞国内外反法西斯阵线的信心。", "event": "斯大林格勒战役", "links": ["苏联利益和人类利益的一致", "目前形势和我们的任务"], "nChars": 3260, "startPage": 583}, {"id": "v3n11", "vol": 3, "title": "祝十月革命二十五周年", "dateRaw": "（一九四二年十一月六日）", "y": 1942, "m": 11, "d": 6, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "值十月革命二十五周年纪念，毛泽东撰文庆祝苏德战争在斯大林格勒战役中的转折，坚信世界反法西斯阵线即将转入反攻，并号召中国人民集中一切力量打击日本法西斯。", "event": "斯大林格勒战役", "links": ["《苏联利益和人类利益的一致》", "《第二次世界大战的转折点》"], "nChars": 414, "startPage": 587}, {"id": "v3n12", "vol": 3, "title": "抗日时期的经济问题和财政问题", "dateRaw": "（一九四二年十二月）", "y": 1942, "m": 12, "d": 1, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "1941-1942年根据地遭日军进攻和国民党封锁，财政经济极度困难；毛泽东在陕甘宁边区高级干部会议上作报告，批判单纯财政观点，提出'发展经济，保障供给'方针，为大生产运动提供纲领。", "event": "延安大生产运动", "links": ["开展根据地的减租、生产和拥政爱民运动", "组织起来", "自己动手，丰衣足食"], "nChars": 3673, "startPage": 588}, {"id": "v3n13", "vol": 3, "title": "关于领导方法的若干问题", "dateRaw": "（一九四三年六月一日）", "y": 1943, "m": 6, "d": 1, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "为中共中央起草关于领导方法的决定，总结1942年整风运动经验，纠正领导工作中一般号召与个别指导脱节、领导骨干与群众脱节的问题，指导各级干部改进领导方法以推进1943年整风。", "event": "延安整风运动", "links": ["整顿党的作风", "反对党八股", "关于整顿三风"], "nChars": 3587, "startPage": 592}, {"id": "v3n14", "vol": 3, "title": "质问国民党", "dateRaw": "（一九四三年七月十二日）", "y": 1943, "m": 7, "d": 12, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "1943年国民党胡宗南部调集兵力、准备闪击延安、掀起新一轮反共高潮，毛泽东为延安《解放日报》撰写社论，揭露国民党破坏团结抗战、消极抗日积极反共的行径，呼吁制止内战危机。", "event": "第三次反共高潮（闪击延安计划）", "links": ["《论联合政府》", "《评国民党十一中全会和三届二次国民参政会》", "《组织起来》"], "nChars": 4359, "startPage": 596}, {"id": "v3n15", "vol": 3, "title": "开展根据地的减租、生产和拥政爱民运动", "dateRaw": "（一九四三年十月一日）", "y": 1943, "m": 10, "d": 1, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "1943年敌后根据地缩小、财政经济极端困难，毛泽东为中共中央起草对党内指示，部署减租、大生产运动和拥政爱民，以发动群众、克服困难、支持长期对敌斗争。", "event": "大生产运动", "links": ["组织起来", "自己动手，丰衣足食", "论联合政府"], "nChars": 2419, "startPage": 601}, {"id": "v3n16", "vol": 3, "title": "评国民党十一中全会和三届二次国民参政会", "dateRaw": "（一九四三年十月五日）", "y": 1943, "m": 10, "d": 5, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "1943年9月国民党十一中全会和三届二次国民参政会表现出反共与对日妥协动摇倾向，毛泽东为延安《解放日报》撰写社论，揭露国民党当局准备内战、破坏团结抗日的动向，教育全国人民认清局势、坚持团结抗战。", "event": "国民党十一中全会及三届二次国民参政会", "links": ["《质问国民党》", "《第二次世界大战的转折点》"], "nChars": 9081, "startPage": 604}, {"id": "v3n17", "vol": 3, "title": "组织起来", "dateRaw": "（一九四三年十一月二十九日）", "y": 1943, "m": 11, "d": 29, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "1943年11月29日中共中央招待陕甘宁边区劳动英雄大会，毛泽东在会上讲话，总结一年来大生产运动的成绩，号召把群众一切力量组织起来，克服经济困难，打败日本帝国主义。", "event": "大生产运动", "links": ["《经济问题与财政问题》", "《自己动手，克服困难》", "《论军队生产自给，兼论整风和生产两大运动的重要性》"], "nChars": 5561, "startPage": 613}, {"id": "v3n18", "vol": 3, "title": "学习和时局", "dateRaw": "（一九四四年四月十二日）", "y": 1944, "m": 4, "d": 12, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "针对1941—1944年党内高级干部学习研究党史、清算1931—1934年'左'倾错误路线过程中提出的问题，毛泽东在延安高级干部会议和中央党校第一部作此讲演，传达中央政治局对几个重要问题的结论，为七大作思想准备。", "event": "延安整风运动", "links": ["整顿党的作风", "反对党八股", "关于若干历史问题的决议"], "nChars": 9895, "startPage": 619}, {"id": "v3n19", "vol": 3, "title": "为人民服务", "dateRaw": "（一九四四年九月八日）", "y": 1944, "m": 9, "d": 8, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "1944年9月5日中央警备团战士张思德在安塞烧炭时牺牲，毛泽东在9月8日的追悼会上发表讲演，借追悼张思德阐明共产党和人民军队为人民服务的根本宗旨，并号召勇于接受批评、团结人民。", "event": "张思德追悼会", "links": ["《在陕甘宁边区参议会的演说》", "《论联合政府》", "《愚公移山》"], "nChars": 1158, "startPage": 629}, {"id": "v3n20", "vol": 3, "title": "评蒋介石在双十节的演说", "dateRaw": "（一九四四年十月十一日）", "y": 1944, "m": 10, "d": 11, "place": "陕西延安", "lat": 36.65, "lng": 109.49, "era": "抗日战争时期", "why": "蒋介石在一九四四年双十节演说中回避人民关切，并为国民党一党专政、抗战不力和拒绝改革辩护。毛泽东以新华社评论揭露其空话及国民党统治危机。", "event": "蒋介石一九四四年双十节演说", "links": [], "nChars": 2606, "startPage": 631}, {"id": "v3n21", "vol": 3, "title": "文化工作中的统一战线", "dateRaw": "（一九四四年十月三十日）", "y": 1944, "m": 10, "d": 30, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "毛泽东在陕甘宁边区文教工作者会议上作此讲演，针对边区文盲众多、迷信盛行、新旧文化力量对立的问题，阐明文化工作中也必须建立广泛统一战线，团结并改造旧知识分子、旧艺人和旧医生，为人民服务。", "event": "陕甘宁边区文教工作者会议", "links": ["《在延安文艺座谈会上的讲话》", "《为人民服务》", "《论联合政府》"], "nChars": 1341, "startPage": 634}, {"id": "v3n22", "vol": 3, "title": "必须学会做经济工作", "dateRaw": "（一九四五年一月十日）", "y": 1945, "m": 1, "d": 10, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "在陕甘宁边区遭受经济封锁、实行大生产运动的背景下，毛泽东在边区劳动英雄和模范工作者大会上讲话，号召党政军工作人员学会经济工作，实现自给自足，为反攻准备物质基础。", "event": "大生产运动", "links": ["组织起来", "自己动手，克服困难"], "nChars": 4152, "startPage": 636}, {"id": "v3n23", "vol": 3, "title": "游击区也能够进行生产", "dateRaw": "（一九四五年一月三十一日）", "y": 1945, "m": 1, "d": 31, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "针对许多人对游击区（敌后之敌后）能否开展大生产运动的怀疑，毛泽东以晋察冀游击队1944年生产运动的成功经验为证据，为《解放日报》撰写社论，推广游击区也必须且能够进行生产的经验。", "event": "大生产运动", "links": ["组织起来", "开展根据地的减租、生产和拥政爱民运动", "自己动手，克服困难"], "nChars": 1965, "startPage": 641}, {"id": "v3n24", "vol": 3, "title": "两个中国之命运", "dateRaw": "（一九四五年四月二十三日）", "y": 1945, "m": 4, "d": 23, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "本文是毛泽东在中共七大上的开幕词。针对抗战胜利在即、中国面临光明与黑暗两种前途的抉择，号召全党放手发动群众、壮大人民力量，争取建设独立自由民主统一富强的新中国。", "event": "中共七大", "links": ["论联合政府", "愚公移山", "抗日战争胜利后的时局和我们的方针"], "nChars": 1743, "startPage": 643}, {"id": "v3n25", "vol": 3, "title": "论联合政府", "dateRaw": "（一九四五年四月二十四日）", "y": 1945, "m": 4, "d": 24, "place": "陕西延安", "lat": 36.65, "lng": 109.489, "era": "抗日战争时期", "why": "抗日战争即将取得胜利，但国内仍存在不团结和政治危机。毛泽东在中共七大上提出建立民主联合政府，以统一抗日力量、争取民族解放并建设新中国。", "event": "中国共产党第七次全国代表大会", "links": ["两个中国之命运", "愚公移山", "抗日战争胜利后的时局和我们的方针"], "nChars": 44743, "startPage": 645}, {"id": "v3n26", "vol": 3, "title": "愚公移山", "dateRaw": "（一九四五年六月十一日）", "y": 1945, "m": 6, "d": 11, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "这是毛泽东在中共七大闭幕时所致的闭幕词，旨在总结大会确定的政治路线、新党章和中央选举三件大事，并用愚公移山的寓言号召全党宣传大会路线、坚定革命必胜信心，动员全党和全国人民挖掉帝国主义和封建主义两座大山。", "event": "中国共产党第七次全国代表大会", "links": ["论联合政府", "两个中国之命运", "关于重庆谈判"], "nChars": 2432, "startPage": 690}, {"id": "v3n27", "vol": 3, "title": "论军队生产自给，兼论整风和生产两大运动的重要性", "dateRaw": "（一九四五年四月二十七日）", "y": 1945, "m": 4, "d": 27, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "为延安《解放日报》撰写社论，针对解放区遭受经济封锁、物质极端困难的状况，号召全军开展生产自给，并强调整风和生产两大运动是夺取抗战胜利的思想与物质基础。", "event": "大生产运动", "links": ["组织起来", "开展根据地的减租、生产和拥政爱民运动", "自己动手，克服困难"], "nChars": 2777, "startPage": 693}, {"id": "v3n28", "vol": 3, "title": "赫尔利和蒋介石的双簧已经破产", "dateRaw": "（一九四五年七月十日）", "y": 1945, "m": 7, "d": 10, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "为新华社撰写评论，揭露美国大使赫尔利支持蒋介石坚持独裁、拒绝联合政府、执意召开包办国民大会的行径，回应1945年7月四届国民参政会上蒋介石的表态，向国内外申明中共立场。", "event": "四届国民参政会", "links": ["论联合政府", "评赫尔利政策的危险", "愚公移山"], "nChars": 2341, "startPage": 696}, {"id": "v3n29", "vol": 3, "title": "评赫尔利政策的危险", "dateRaw": "（一九四五年七月十二日）", "y": 1945, "m": 7, "d": 12, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "1945年4月赫尔利在华盛顿发表声明公开支持国民党、抛弃延安曾赞同的联合政府方案，扶蒋反共助长内战危机；毛泽东为新华社撰写评论，揭露和警告美国对华政策的危险性，为中共应对抗战胜利前后的局势作舆论准备。", "event": "赫尔利扶蒋反共政策", "links": ["论联合政府", "愚公移山", "赫尔利和蒋介石的双簧已经破产"], "nChars": 1105, "startPage": 699}, {"id": "v3n30", "vol": 3, "title": "给福斯特同志的电报", "dateRaw": "（一九四五年七月二十九日）", "y": 1945, "m": 7, "d": 29, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "为祝贺美国共产主义政治协会特别会议抛弃白劳德修正主义路线、重建美国共产党而致电福斯特，同时揭露美国反动资本集团支持国民党反动派、制造中国内战危机的图谋。", "event": "美国共产党重建", "links": ["《论联合政府》", "《愚公移山》"], "nChars": 890, "startPage": 701}, {"id": "v3n31", "vol": 3, "title": "对日寇的最后一战", "dateRaw": "（一九四五年八月九日）", "y": 1945, "m": 8, "d": 9, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "苏联于8月8日对日宣战，日本败局已定，毛泽东立即发表声明，号召全国抗日力量举行大反攻，配合苏军作战，夺取最后胜利，并防止内战危险。", "event": "苏联对日宣战、抗日战争大反攻", "links": ["《团结起来，划清敌我界限》", "《第十八集团军总司令给蒋介石的两个电报》", "《蒋介石在挑动内战》"], "nChars": 563, "startPage": 702}, {"id": "v4n01", "vol": 4, "title": "抗日战争胜利后的时局和我们的方针", "dateRaw": "（一九四五年八月十三日）", "y": 1945, "m": 8, "d": 13, "place": "延安市", "lat": 36.58, "lng": 109.49, "era": "解放战争时期", "why": "抗战胜利后蒋介石在美国支持下准备抢夺胜利果实并发动内战，毛泽东在延安干部会议上发表讲演，分析时局并提出针锋相对的革命策略方针。", "event": "抗战胜利后的国共对峙", "links": ["论联合政府", "蒋介石在挑动内战", "中共中央关于同国民党进行和平谈判的通知"], "nChars": 9573, "startPage": 704}, {"id": "v4n02", "vol": 4, "title": "蒋介石在挑动内战", "dateRaw": "（一九四五年八月十三日）", "y": 1945, "m": 8, "d": 13, "place": "陕西省延安市", "lat": 36.5853, "lng": 109.4897, "era": "抗日战争时期", "why": "日本宣布投降后，蒋介石命令解放区军队原地待命并限制其接受日伪投降。毛泽东为揭露国民党借受降问题排斥、限制共产党军队并准备发动内战而写此评论。", "event": "日本投降与受降争夺", "links": ["抗日战争胜利后的时局和我们的方针", "第十八集团军给蒋介石的两个电报", "评蒋介石发言人谈话"], "nChars": 2727, "startPage": 714}, {"id": "v4n03", "vol": 4, "title": "第十八集团军总司令给蒋介石的两个电报", "dateRaw": "（一九四五年八月）", "y": 1945, "m": 8, "d": 1, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "抗日战争时期", "why": "日本宣布投降之际，蒋介石垄断受降权并命令解放区部队'原地驻防待命'，同时调兵准备内战。毛泽东代朱德起草电报，揭露蒋介石内战阴谋，教育全国人民提高警惕，并提出制止内战的六项主张。", "event": "抗日战争胜利受降之争", "links": ["蒋介石在挑动内战", "评蒋介石发言人谈话", "关于重庆谈判"], "nChars": 4328, "startPage": 717}, {"id": "v4n04", "vol": 4, "title": "评蒋介石发言人谈话", "dateRaw": "（一九四五年八月十六日）", "y": 1945, "m": 8, "d": 16, "place": "陕西延安", "lat": 36.5965, "lng": 109.489, "era": "抗日战争时期", "why": "日本投降前后，蒋介石以命令限制八路军、新四军和人民军队受降、作战，并借发言人谈话威胁“违反者”为“人民公敌”。毛泽东据此揭露其发动全面内战、抢夺抗战胜利果实的意图。", "event": "日本投降与国共战后争夺", "links": ["抗日战争胜利后的时局和我们的方针", "中共中央对目前时局的宣言"], "nChars": 2559, "startPage": 722}, {"id": "v4n05", "vol": 4, "title": "中共中央关于同国民党进行和平谈判的通知", "dateRaw": "（一九四五年八月二十六日）", "y": 1945, "m": 8, "d": 26, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "解放战争时期", "why": "日本投降后蒋介石三次电邀毛泽东赴重庆谈判，毛泽东在赴渝前两天为中共中央起草党内通知，分析形势、说明谈判方针与让步准备，告诫全党不要因谈判而放松对蒋介石的警惕和斗争。", "event": "重庆谈判", "links": ["关于重庆谈判", "抗日战争胜利后的时局和我们的方针", "蒋介石在挑动内战"], "nChars": 2526, "startPage": 725}, {"id": "v4n06", "vol": 4, "title": "关于重庆谈判", "dateRaw": "（一九四五年十月十七日）", "y": 1945, "m": 10, "d": 17, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "解放战争时期", "why": "毛泽东从重庆谈判返回延安后，向延安干部说明谈判的成果与局限，揭露国民党一边谈判一边进攻解放区的两面手法，阐明'针锋相对，寸土必争'的方针以统一党内认识。", "event": "重庆谈判", "links": ["抗日战争胜利后的时局和我们的方针", "中共中央关于同国民党进行和平谈判的通知", "和美国记者安娜·路易斯·斯特朗的谈话"], "nChars": 7793, "startPage": 728}, {"id": "v4n07", "vol": 4, "title": "国民党进攻的真相", "dateRaw": "（一九四五年十一月五日）", "y": 1945, "m": 11, "d": 5, "place": "陕西延安", "lat": 36.5854, "lng": 109.6098, "era": "解放战争时期", "why": "蒋介石撕毁《双十协定》后大规模进攻解放区，国民党宣传部长吴国桢谎称政府'全居守势'，毛泽东以中共发言人名义发表谈话，用上党战役、邯郸战役等事实驳斥谎言，揭露国民党挑动内战的真相，争取国内外舆论。", "event": "上党战役、邯郸战役（平汉战役）", "links": ["蒋介石在挑动内战", "关于重庆谈判", "减租和生产是保卫解放区的两件大事"], "nChars": 3079, "startPage": 736}, {"id": "v4n08", "vol": 4, "title": "减租和生产是保卫解放区的两件大事", "dateRaw": "（一九四五年十一月七日）", "y": 1945, "m": 11, "d": 7, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "解放战争时期", "why": "抗战胜利后国民党在美国援助下进攻解放区，内战已成事实。毛泽东为中共中央起草党内指示，要求通过减租发动农民、通过生产保障供给，以粉碎国民党进攻、保卫解放区。", "event": "重庆谈判后的国共内战爆发（上党战役、平汉战役时期）", "links": ["建立巩固的东北根据地", "一九四六年解放区工作的方针", "以自卫战争粉碎蒋介石的进攻"], "nChars": 1143, "startPage": 740}, {"id": "v4n09", "vol": 4, "title": "一九四六年解放区工作的方针", "dateRaw": "（一九四五年十二月十五日）", "y": 1945, "m": 12, "d": 15, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "解放战争时期", "why": "抗战胜利后国民党调集兵力准备进攻解放区，内战一触即发。毛泽东为中共中央起草党内指示，为各解放区部署一九四六年的工作方针，以粉碎国民党新的进攻。", "event": "重庆谈判后的内战危机、高树勋起义（邯郸战役）", "links": ["抗日战争胜利后的时局和我们的方针", "建立巩固的东北根据地", "以自卫战争粉碎蒋介石的进攻"], "nChars": 2852, "startPage": 742}, {"id": "v4n10", "vol": 4, "title": "建立巩固的东北根据地", "dateRaw": "（一九四五年十二月二十八日）", "y": 1945, "m": 12, "d": 28, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "解放战争时期", "why": "抗战胜利后国共争夺东北，国民党在美援下大举运兵攻占山海关、锦州等地，东北严重斗争不可避免；毛泽东为中共中央起草给东北局的指示，确定在远离国民党占领中心的东满、北满、西满乡村建立巩固根据地，发动群众、积蓄力量准备将来反攻。", "event": "抗战胜利后国共争夺东北", "links": ["抗日战争胜利后的时局和我们的方针", "关于重庆谈判", "以自卫战争粉碎蒋介石的进攻"], "nChars": 2945, "startPage": 745}, {"id": "v4n11", "vol": 4, "title": "关于目前国际形势的几点估计", "dateRaw": "（一九四六年四月）", "y": 1946, "m": 4, "d": 1, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "解放战争时期", "why": "针对1946年春部分同志因'美苏必战'、'第三次世界大战必然爆发'的鼓吹而对帝国主义力量估计过高、在美蒋进攻面前软弱动摇的悲观情绪，毛泽东写下此文予以纠正，坚定以革命战争反对反革命战争的信心。", "event": "解放战争初期（全面内战爆发前）", "links": ["和美国记者安娜·路易斯·斯特朗的谈话", "以自卫战争粉碎蒋介石的进攻", "目前形势和我们的任务"], "nChars": 981, "startPage": 748}, {"id": "v4n12", "vol": 4, "title": "以自卫战争粉碎蒋介石的进攻", "dateRaw": "（一九四六年七月二十日）", "y": 1946, "m": 7, "d": 20, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "解放战争时期", "why": "1946年6月底蒋介石发动全面内战后，毛泽东为中共中央起草党内指示，分析敌我力量对比，阐明战胜蒋介石的方针与方法，动员全党和解放区军民以自卫战争粉碎国民党军的全面进攻。", "event": "全面内战爆发、中原突围", "links": ["抗日战争胜利后的时局和我们的方针", "集中优势兵力，各个歼灭敌人", "和美国记者安娜·路易斯·斯特朗的谈话"], "nChars": 4426, "startPage": 749}, {"id": "v4n13", "vol": 4, "title": "和美国记者安娜·路易斯·斯特朗的谈话", "dateRaw": "（一九四六年八月六日）", "y": 1946, "m": 8, "d": 6, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "解放战争时期", "why": "抗战胜利后国民党在美国支持下准备发动全面内战，毛泽东接受美国记者斯特朗采访，提出'一切反动派都是纸老虎'的论断，以回应敌强我弱形势下部分人对战争前途的疑惧，鼓舞解放区军民的胜利信心。", "event": "全面内战爆发", "links": ["目前形势和我们的任务", "和美国记者安娜·路易斯·斯特朗的谈话", "关于重庆谈判"], "nChars": 3922, "startPage": 754}, {"id": "v4n14", "vol": 4, "title": "集中优势兵力，各个歼灭敌人", "dateRaw": "（一九四六年九月十六日）", "y": 1946, "m": 9, "d": 16, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "解放战争时期", "why": "1946年6月全面内战爆发后，面对国民党军大举进攻解放区，毛泽东为中央军委起草党内指示，纠正平分兵力的错误战法，确立集中优势兵力、各个歼灭敌人的作战原则，指导各解放区部队作战。", "event": "苏中战役、定陶战役", "links": ["以自卫战争粉碎蒋介石的进攻", "三个月总结", "和美国记者安娜·路易斯·斯特朗的谈话"], "nChars": 2955, "startPage": 758}, {"id": "v4n15", "vol": 4, "title": "美国“调解”真相和中国内战前途", "dateRaw": "（一九四六年九月二十九日）", "y": 1946, "m": 9, "d": 29, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "解放战争时期", "why": "全面内战爆发后，美国以马歇尔调处为名援助蒋介石打内战。毛泽东借答美国记者斯蒂尔之问，揭露美国'调解'真相，向中外宣告中国人民争取独立、和平、民主的决心和内战前途。", "event": "全面内战爆发与马歇尔调处", "links": ["和美国记者安娜·路易斯·斯特朗的谈话", "以自卫战争粉碎蒋介石的进攻", "关于重庆谈判"], "nChars": 1898, "startPage": 761}, {"id": "v4n16", "vol": 4, "title": "三个月总结", "dateRaw": "（一九四六年十月一日）", "y": 1946, "m": 10, "d": 1, "place": "陕西延安", "lat": 36.58, "lng": 109.49, "era": "解放战争时期", "why": "1946年6月底蒋介石发动全面内战，三个月作战后毛泽东为中共中央起草对党内指示，总结7-9月作战经验，论证'我必胜蒋必败'，并部署今后歼敌任务和解放区土改、生产等配合工作。", "event": "解放战争战略防御阶段（全面内战爆发初期）", "links": ["以自卫战争粉碎蒋介石的进攻", "集中优势兵力，各个歼灭敌人", "和美国记者安娜·路易斯·斯特朗的谈话"], "nChars": 3859, "startPage": 763}, {"id": "v4n17", "vol": 4, "title": "迎接中国革命的新高潮", "dateRaw": "（一九四七年二月一日）", "y": 1947, "m": 2, "d": 1, "place": "延安", "lat": 36.58, "lng": 109.49, "era": "解放战争时期", "why": "全面内战爆发后七个月解放军已歼灭蒋军五十六个旅，军事形势转向有利于人民，毛泽东为中共中央起草指示，向党内指明时局将发展到新的革命高潮前夜，并部署争取高潮到来的任务", "event": "解放战争内线防御作战", "links": ["以自卫战争粉碎蒋介石的进攻", "三个月总结", "集中优势兵力，各个歼灭敌人"], "nChars": 5371, "startPage": 767}, {"id": "v4n18", "vol": 4, "title": "中共中央关于暂时放弃延安和保卫陕甘宁边区的两个文件", "dateRaw": "（一九四六年十一月、一九四七年四月）", "y": 1946, "m": 11, "d": 1, "place": "陕北靖边县青阳岔(其一为延安)", "lat": 37.6, "lng": 108.8, "era": "解放战争时期", "why": "国民党军1947年3月占领延安后,毛泽东起草中共中央两个文件:前一篇在国民党准备进攻延安时(1946年冬于延安)动员军民 temporarily 放弃延安、保卫陕甘宁边区;后一篇在延安失守二十天后(于靖边县青阳岔)部署以延安空城诱敌深入、在运动中歼敌的方针。", "event": "国民党重点进攻与转战陕北", "links": ["关于西北战场的作战方针", "目前形势和我们的任务"], "nChars": 1989, "startPage": 773}, {"id": "v4n19", "vol": 4, "title": "关于西北战场的作战方针", "dateRaw": "（一九四七年四月十五日）", "y": 1947, "m": 4, "d": 15, "place": "陕北靖边县青阳岔", "lat": 37.3, "lng": 108.8, "era": "解放战争时期", "why": "1947年3月中共中央撤出延安后，胡宗南部重兵追击中共中央和西北野战兵团。毛泽东在此电中为西北野战兵团确立'蘑菇'战术，即与敌周旋使其十分疲劳缺粮后再寻机歼灭，以粉碎国民党军对陕北的重点进攻。", "event": "转战陕北、青化砭战役", "links": ["关于西北野战军的作战方针", "解放战争第二年的战略方针", "目前形势和我们的任务"], "nChars": 911, "startPage": 776}, {"id": "v4n20", "vol": 4, "title": "蒋介石政府已处在全民的包围中", "dateRaw": "（一九四七年五月三十日）", "y": 1947, "m": 5, "d": 30, "place": "陕北靖边县王家湾", "lat": 37.2833, "lng": 108.6833, "era": "解放战争时期", "why": "1947年5月，国民党在军事进攻受挫的同时，因饥饿、内战、迫害引发全国性学生运动，形成反对蒋介石的第二条战线。毛泽东为新华社撰写评论，指出蒋介石政府已处在全民包围中，号召人民为全国胜利迅速准备条件。", "event": "第二条战线（反饥饿反内战反迫害学生运动）", "links": ["关于西北战场的作战方针", "以自卫战争粉碎蒋介石的进攻", "和美国记者安娜·路易斯·斯特朗的谈话"], "nChars": 3040, "startPage": 777}, {"id": "v4n21", "vol": 4, "title": "解放战争第二年的战略方针", "dateRaw": "（一九四七年九月一日）", "y": 1947, "m": 9, "d": 1, "place": "陕北佳县朱官寨", "lat": 38.26, "lng": 110.42, "era": "解放战争时期", "why": "解放战争进入第二年，为中共中央起草的对党内指示，规定由战略防御转入战略进攻、由内线作战转入外线作战、主力打到国民党区域的基本任务，统一全党全军的战略认识。", "event": "解放军转入战略进攻（刘邓大军挺进大别山）", "links": ["目前形势和我们的任务", "以自卫战争粉碎蒋介石的进攻", "集中优势兵力，各个歼灭敌人"], "nChars": 3957, "startPage": 781}, {"id": "v4n22", "vol": 4, "title": "中国人民解放军宣言", "dateRaw": "（一九四七年十月十日）", "y": 1947, "m": 10, "d": 10, "place": "陕北佳县神泉堡", "lat": 38.26, "lng": 110.49, "era": "解放战争时期", "why": "1947年解放军由战略防御转入战略反攻，毛泽东为中国人民解放军总部起草政治宣言，分析国内政治形势，提出'打倒蒋介石，解放全中国'的口号并宣布八项基本政策，以动员全国人民支援解放战争。", "event": "解放战争战略反攻", "links": ["目前形势和我们的任务", "以自卫战争粉碎蒋介石的进攻", "中国人民解放军总部关于重行颁布三大纪律八项注意的训令"], "nChars": 3472, "startPage": 785}, {"id": "v4n23", "vol": 4, "title": "中国人民解放军总部关于重行颁布三大纪律八项注意的训令", "dateRaw": "（一九四七年十月十日）", "y": 1947, "m": 10, "d": 10, "place": "陕北佳县（转战陕北期间，佳县神泉堡一带）", "lat": 38.26, "lng": 110.49, "era": "解放战争时期", "why": "解放战争进入战略反攻阶段，部队大扩充、作战地域扩大，各地各军执行三大纪律八项注意的内容出现出入，为统一全军纪律、加强部队教育与团结群众而以训令形式重行颁布。", "event": "转战陕北、中国人民解放军转入战略进攻", "links": ["中国人民解放军宣言", "目前形势和我们的任务", "关于建立报告制度"], "nChars": 747, "startPage": 789}, {"id": "v4n24", "vol": 4, "title": "目前形势和我们的任务", "dateRaw": "（一九四七年十二月二十五日）", "y": 1947, "m": 12, "d": 25, "place": "陕北米脂县杨家沟", "lat": 38.1833, "lng": 110.1667, "era": "解放战争时期", "why": "在人民解放军转入战略进攻、解放战争达到转折点的关键时期，为中共中央十二月会议所作的报告，为打倒蒋介石反动统治、建立新民主主义中国制定政治、军事、经济各方面的纲领性文件。", "event": "中国人民解放军转入战略进攻（十二月会议）", "links": ["中国人民解放军宣言", "关于目前国际形势的几点估计", "关于目前党的政策中的几个重要问题"], "nChars": 13867, "startPage": 790}, {"id": "v4n25", "vol": 4, "title": "关于建立报告制度", "dateRaw": "（一九四八年一月七日）", "y": 1948, "m": 1, "d": 7, "place": "陕西米脂县杨家沟", "lat": 37.87, "lng": 110.17, "era": "解放战争时期", "why": "解放战争胜利在望、解放区连成一片的新形势下，为克服党内军内的无纪律无政府状态，加强中央集中统一领导，毛泽东为中共中央起草对党内的指示，建立各中央局、分局书记定期向中央作综合报告的制度。", "event": "转战陕北", "links": ["一九四八年的土地改革工作和整党工作", "中共中央关于九月会议的通知", "关于健全党委制"], "nChars": 1562, "startPage": 803}, {"id": "v4n26", "vol": 4, "title": "关于目前党的政策中的几个重要问题", "dateRaw": "（一九四八年一月十八日）", "y": 1948, "m": 1, "d": 18, "place": "陕北米脂县杨家沟", "lat": 37.754, "lng": 110.185, "era": "解放战争时期", "why": "解放战争转入进攻、土地改革全面展开之际，党内出现对敌力量估计过高和土改中'左'、右两种错误倾向；毛泽东为中共中央起草此决定草案，系统阐明党内反对错误倾向和土改、群众运动中的具体政策，以纠正偏向、统一全党政策思想。", "event": "转战陕北、解放区土地改革运动", "links": ["目前形势和我们的任务", "关于建立报告制度", "在晋绥干部会议上的讲话"], "nChars": 4213, "startPage": 805}, {"id": "v4n27", "vol": 4, "title": "军队内部的民主运动", "dateRaw": "（一九四八年一月三十日）", "y": 1948, "m": 1, "d": 30, "place": "陕北米脂县杨家沟", "lat": 37.75, "lng": 110.15, "era": "解放战争时期", "why": "解放战争转入战略进攻、部队开展新式整军运动（三查三整）之际，毛泽东为中央军委起草党内指示，总结并推广军队内部政治民主、经济民主、军事民主的经验，以巩固部队团结、提高战斗力。", "event": "新式整军运动（三查三整）", "links": ["目前形势和我们的任务", "关于建立报告制度", "在晋绥干部会议上的讲话"], "nChars": 850, "startPage": 810}, {"id": "v4n28", "vol": 4, "title": "在不同地区实施土地法的不同策略", "dateRaw": "（一九四八年二月三日）", "y": 1948, "m": 2, "d": 3, "place": "陕北杨家沟", "lat": 37.6, "lng": 110.2, "era": "解放战争时期", "why": "1947年《中国土地法大纲》颁布后，各解放区情况差异很大，出现一刀切执行的问题。毛泽东就此电告刘少奇，说明老解放区、半老区和新解放区应采取不同的土地法实施策略，以纠正土改中的偏差。", "event": "解放区土地改革", "links": ["目前形势和我们的任务", "关于建立报告制度", "纠正土地改革宣传中的“左”倾错误"], "nChars": 1195, "startPage": 811}, {"id": "v4n29", "vol": 4, "title": "纠正土地改革宣传中的“左”倾错误", "dateRaw": "（一九四八年二月十一日）", "y": 1948, "m": 2, "d": 11, "place": "陕北米脂县杨家沟", "lat": 37.7833, "lng": 110.1833, "era": "解放战争时期", "why": "针对土地改革和整党运动中各地宣传媒介（通讯社、报纸、广播）传播“左”倾错误倾向、造成错误舆论空气的问题，毛泽东为中共中央起草党内指示，纠正宣传工作中的“左”倾偏向，重申党的正确路线。", "event": "解放区土地改革运动", "links": ["目前形势和我们的任务", "关于目前党的政策中的几个重要问题", "在晋绥干部会议上的讲话"], "nChars": 1151, "startPage": 813}, {"id": "v4n30", "vol": 4, "title": "新解放区土地改革要点", "dateRaw": "（一九四八年二月十五日）", "y": 1948, "m": 2, "d": 15, "place": "陕北", "lat": 38.5, "lng": 110.0, "era": "解放战争时期", "why": "1948年初解放军转入战略进攻后新解放区迅速扩大，为纠正新区土改中急于求成、打击面过宽等‘左’的倾向，毛泽东为中共中央起草此党内指示，规范新区土地改革的步骤和政策。", "event": "解放区土地改革运动", "links": ["目前形势和我们的任务", "关于建立报告制度", "在晋绥干部会议上的讲话"], "nChars": 924, "startPage": 815}, {"id": "v4n31", "vol": 4, "title": "关于工商业政策", "dateRaw": "（一九四八年二月二十七日）", "y": 1948, "m": 2, "d": 27, "place": "陕北米脂县杨家沟", "lat": 37.85, "lng": 110.18, "era": "解放战争时期", "why": "解放战争转入进攻、许多城市即将解放之际，某些地方党组织把农村土改斗争办法错误地搬到城市，破坏工商业。毛泽东为中共中央起草党内指示，纠正偏向，明确保护工商业、公私兼顾劳资两利的政策。", "event": "解放战争战略进攻与新区城市接管", "links": ["目前形势和我们的任务", "关于目前党的政策中的几个重要问题", "在晋绥干部会议上的讲话"], "nChars": 1135, "startPage": 816}, {"id": "v4n32", "vol": 4, "title": "关于民族资产阶级和开明绅士问题", "dateRaw": "（一九四八年三月一日）", "y": 1948, "m": 3, "d": 1, "place": "陕西米脂县杨家沟", "lat": 37.7833, "lng": 110.1667, "era": "解放战争时期", "why": "1948年3月毛泽东转战陕北期间仍驻杨家沟，土地改革和整党运动中部分地区出现'左'的偏向，错待了与共产党合作的民族资产阶级和开明绅士。他为中共中央起草党内指示，纠正土改中的'左'倾错误，阐明对民族资产阶级和开明绅士的团结政策，说明革命的性质是新民主主义革命而非社会主义革命。", "event": "解放区土地改革运动", "links": ["目前形势和我们的任务", "中国人民解放军宣言", "关于目前党的政策中的几个重要问题"], "nChars": 2292, "startPage": 818}, {"id": "v4n33", "vol": 4, "title": "评西北大捷兼论解放军的新式整军运动", "dateRaw": "（一九四八年三月七日）", "y": 1948, "m": 3, "d": 7, "place": "陕北米脂县杨家沟", "lat": 37.85, "lng": 110.18, "era": "解放战争时期", "why": "宜川大捷后西北战场敌军进攻被粉碎、解放军转入进攻，毛泽东为解放军总部发言人起草评论，分析西北及全国战场形势，并着重阐述以'诉苦''三查'为方法的新式整军运动对提高部队政治觉悟和战斗力的重大意义。", "event": "宜川战役（西北大捷）", "links": ["军队内部的民主运动", "在晋绥干部会议上的讲话", "中共中央关于九月会议的通知"], "nChars": 4406, "startPage": 821}, {"id": "v4n34", "vol": 4, "title": "关于情况的通报", "dateRaw": "（一九四八年三月二十日）", "y": 1948, "m": 3, "d": 20, "place": "陕北米脂县杨家沟", "lat": 37.7833, "lng": 110.1833, "era": "解放战争时期", "why": "在解放战争转入进攻、大片新区开辟的形势下，党内土改、工商业、统一战线等工作中出现严重'左'的偏向，毛泽东为中共中央向党内各级领导通报形势与政策，纠正偏向，强调'政策和策略是党的生命'。", "event": "转战陕北、土地改革运动", "links": ["目前形势和我们的任务", "关于建立报告制度", "在晋绥干部会议上的讲话"], "nChars": 4868, "startPage": 826}, {"id": "v4n35", "vol": 4, "title": "在晋绥干部会议上的讲话", "dateRaw": "（一九四八年四月一日）", "y": 1948, "m": 4, "d": 1, "place": "山西兴县蔡家崖（晋绥解放区首府）", "lat": 38.4667, "lng": 111.1333, "era": "解放战争时期", "why": "毛泽东1948年东渡黄河转战华北途中，在晋绥解放区首府兴县蔡家崖对晋绥干部总结该区土地改革和整党工作的成功经验，既纠正运动中'左'右偏向，又阐明党在新民主主义革命时期的总路线和土改总路线，以指导全国工作。", "event": "解放区土地改革运动", "links": ["目前形势和我们的任务", "关于目前党的政策中的几个重要问题", "在晋绥干部会议上的讲话（相关联：纠正土地改革宣传中的'左'倾错误——《在晋绥日报编辑部的谈话》/即《对晋绥日报编辑人员的谈话》）"], "nChars": 8077, "startPage": 831}, {"id": "v4n36", "vol": 4, "title": "对晋绥日报编辑人员的谈话", "dateRaw": "（一九四八年四月二日）", "y": 1948, "m": 4, "d": 2, "place": "山西兴县蔡家崖（晋绥解放区）", "lat": 38.4642, "lng": 111.1337, "era": "解放战争时期", "why": "1948年毛泽东率中央机关转战陕北后东渡黄河，途经晋绥解放区，在土地改革和整党运动中针对部分领导机关不让群众了解政策、群众路线贯彻不力的问题，向晋绥日报编辑人员阐述办报要宣传党的政策、联系群众的道理。", "event": "转战陕北结束后东渡黄河、晋绥土改整党", "links": ["在晋绥干部会议上的讲话", "关于建立报告制度", "纠正土地改革宣传中的右倾错误"], "nChars": 2897, "startPage": 839}, {"id": "v4n37", "vol": 4, "title": "再克洛阳后给洛阳前线指挥部的电报", "dateRaw": "（一九四八年四月八日）", "y": 1948, "m": 4, "d": 8, "place": "山西临县双塔村（转战陕北结束后东渡黄河，经晋绥解放区）", "lat": 37.9, "lng": 110.9, "era": "解放战争时期", "why": "1948年3月人民解放军再次攻克洛阳后，为纠正新解放城市接管中可能出现的过激做法，毛泽东为中共中央起草电报，系统规定城市政策；因内容具有普遍性，同时发给其他前线和地区领导参考。", "event": "洛阳战役（再克洛阳）", "links": ["目前形势和我们的任务", "关于辽沈战役的作战方针", "中国人民解放军布告"], "nChars": 1167, "startPage": 842}, {"id": "v4n38", "vol": 4, "title": "新解放区农村工作的策略问题", "dateRaw": "（一九四八年五月二十四日）", "y": 1948, "m": 5, "d": 24, "place": "河北阜平县城南庄", "lat": 38.85, "lng": 114.15, "era": "解放战争时期", "why": "解放战争推进中大量新解放区出现，部分地区过早分浮财分土地造成群众不满、社会财富分散、军需负担失当。毛泽东电复邓小平，指出新解放区须先经历减租减息阶段，暂缓土地改革，以稳定秩序、集中力量消灭国民党军。", "event": "解放战争转入战略进攻、新区土地政策调整", "links": ["目前形势和我们的任务", "在晋绥干部会议上的讲话", "一九四八年的土地改革工作和整党工作"], "nChars": 570, "startPage": 844}, {"id": "v4n39", "vol": 4, "title": "一九四八年的土地改革工作和整党工作", "dateRaw": "（一九四八年五月二十五日）", "y": 1948, "m": 5, "d": 25, "place": "河北阜平县城南庄", "lat": 38.85, "lng": 114.15, "era": "解放战争时期", "why": "为纠正土改和整党工作中出现的‘左’的偏向、规范工作步骤而对党内起草的指示，要求各地按季节和条件完成土地改革、整党及转向生产的工作，以巩固后方并支援战争。", "event": "解放区土地改革运动", "links": ["目前形势和我们的任务", "在晋绥干部会议上的讲话", "关于建立报告制度"], "nChars": 3219, "startPage": 845}, {"id": "v4n40", "vol": 4, "title": "关于辽沈战役的作战方针", "dateRaw": "（一九四八年九月、十月）", "y": 1948, "m": 9, "d": 1, "place": "河北西柏坡", "lat": 38.35, "lng": 113.95, "era": "解放战争时期", "why": "1948年9月中共中央移驻西柏坡期间，毛泽东为中央军委起草给林彪、罗荣桓等的电报，部署东北野战军攻克锦州、封闭敌军于东北予以歼灭的辽沈战役作战方针，以实现五年左右根本上打倒国民党的战略目标。", "event": "辽沈战役", "links": ["关于淮海战役的作战方针", "关于平津战役的作战方针", "关于健全党委制"], "nChars": 3805, "startPage": 849}, {"id": "v4n41", "vol": 4, "title": "关于健全党委制", "dateRaw": "（一九四八年九月二十日）", "y": 1948, "m": 9, "d": 20, "place": "河北西柏坡", "lat": 38.3539, "lng": 113.9511, "era": "解放战争时期", "why": "解放战争规模扩大、任务繁重，党内一些领导机关存在个人包办取代集体领导的习气。毛泽东为中共中央起草此决定，旨在健全党委会议制度，保证集体领导、防止个人包办，以适应夺取全国胜利的需要。", "event": "解放战争战略决战（辽沈、淮海、平津战役前夕）", "links": ["《关于建立报告制度》", "《关于情况的通报》", "《党委会的工作方法》"], "nChars": 925, "startPage": 853}, {"id": "v4n42", "vol": 4, "title": "中共中央关于九月会议的通知", "dateRaw": "（一九四八年十月十日）", "y": 1948, "m": 10, "d": 10, "place": "河北平山县西柏坡", "lat": 38.3531, "lng": 113.9403, "era": "解放战争时期", "why": "九月政治局会议后，毛泽东为中共中央起草党内通知，向各中央局、分局传达会议对过去工作的检查和今后任务的部署，统一全党在战略决战阶段的方针，并为召开七届二中全会做准备。", "event": "九月会议（1948年中央政治局会议）", "links": ["《目前形势和我们的任务", "《中国人民解放军宣言", "《关于建立报告制度"], "nChars": 5777, "startPage": 854}, {"id": "v4n43", "vol": 4, "title": "关于淮海战役的的作战方针", "dateRaw": "（一九四八年十月十一日）", "y": 1948, "m": 10, "d": 11, "place": "河北平山县西柏坡", "lat": 38.36, "lng": 113.84, "era": "解放战争时期", "why": "1948年秋战略决战展开之际，毛泽东为中央军委起草电报给华东野战军（并告华东局、中原局），针对在徐州地区歼灭国民党军刘峙集团的问题，提出淮海战役分阶段的作战部署方针。", "event": "淮海战役", "links": ["关于辽沈战役的作战方针", "关于平津战役的作战方针", "目前形势和我们的任务"], "nChars": 2910, "startPage": 860}, {"id": "v4n44", "vol": 4, "title": "全世界革命力量团结起来，反对帝国主义的侵略", "dateRaw": "（一九四八年十一月）", "y": 1948, "m": 11, "d": 1, "place": "河北西柏坡", "lat": 38.35, "lng": 113.95, "era": "解放战争时期", "why": "为纪念十月革命三十一周年，应欧洲共产党和工人党情报局机关刊之约而写，阐述十月革命的世界意义，号召全世界革命力量在以苏联为首的反帝阵线下团结起来，反对帝国主义侵略。", "event": "十月革命三十一周年纪念、辽沈战役结束后的战略决战阶段", "links": ["《目前形势和我们的任务》", "《和美国记者安娜·路易斯·斯特朗的谈话》", "《“友谊”，还是侵略？》"], "nChars": 2340, "startPage": 863}, {"id": "v4n45", "vol": 4, "title": "中国军事形势的重大变化", "dateRaw": "（一九四八年十一月十四日）", "y": 1948, "m": 11, "d": 14, "place": "河北西柏坡", "lat": 38.35, "lng": 113.95, "era": "解放战争时期", "why": "辽沈战役胜利后敌我力量对比发生根本变化，毛泽东为新华社撰写评论，据此重新估计解放战争胜利时间，指出再有一年左右即可打倒国民党反动统治，以鼓舞军民士气。", "event": "辽沈战役", "links": ["目前形势和我们的任务", "关于辽沈战役的作战方针", "中国革命战争的战略问题"], "nChars": 1468, "startPage": 866}, {"id": "v4n46", "vol": 4, "title": "关于平津战役的作战方针", "dateRaw": "（一九四八年十二月十一日）", "y": 1948, "m": 12, "d": 11, "place": "河北西柏坡", "lat": 38.35, "lng": 113.94, "era": "解放战争时期", "why": "辽沈战役结束后东北野战军秘密入关，为统一林罗大军与华北兵团的协同指挥、防止平津之敌从海上南逃，毛泽东为中央军委起草电报，规定先围塘沽、天津，隔而不围、围而不打的战役部署。", "event": "平津战役", "links": ["关于辽沈战役的作战方针", "关于淮海战役的作战方针"], "nChars": 3058, "startPage": 868}, {"id": "v4n47", "vol": 4, "title": "敦促杜聿明等投降书", "dateRaw": "（一九四八年十二月十七日）", "y": 1948, "m": 12, "d": 17, "place": "河北平山县西柏坡", "lat": 38.35, "lng": 113.94, "era": "解放战争时期", "why": "淮海战役后期，黄维兵团已被歼灭，杜聿明、邱清泉、李弥两兵团被围困于陈官庄地区，山穷水尽。毛泽东为中原、华东两人民解放军司令部撰写广播稿，劝杜聿明等放下武器投降，以减少伤亡、瓦解敌军斗志。", "event": "淮海战役", "links": ["关于淮海战役的作战方针", "评国民党对战争负责问题的几种花样", "南京政府向何处去？"], "nChars": 1610, "startPage": 872}, {"id": "v4n48", "vol": 4, "title": "将革命进行到底", "dateRaw": "（一九四八年十二月三十日）", "y": 1948, "m": 12, "d": 30, "place": "河北平山县西柏坡", "lat": 38.3578, "lng": 113.9417, "era": "解放战争时期", "why": "这是毛泽东为新华社写的1949年新年献词。三大战役胜利在望、国民党企图'和谈'以喘息，文章针对党内和民主人士中出现的妥协幻想，号召人民将革命进行到底，坚决推翻国民党统治。", "event": "三大战役（辽沈、淮海、平津）", "links": ["目前形势和我们的任务", "在中国共产党第七届中央委员会第二次全体会议上的报告", "评战犯求和"], "nChars": 6014, "startPage": 874}, {"id": "v4n49", "vol": 4, "title": "评战犯求和", "dateRaw": "（一九四九年一月四日）", "y": 1949, "m": 1, "d": 4, "place": "河北西柏坡", "lat": 38.35, "lng": 113.94, "era": "解放战争时期", "why": "1949年1月蒋介石元旦发表求和声明，企图借和平谈判保存国民党反动实力和美国在华势力。毛泽东为新华社撰写评论予以揭露，帮助中国人民识破假和平阴谋，将革命进行到底。", "event": "三大战役", "links": ["将革命进行到底", "四分五裂的反动派为什么还要空喊“全面和平”？", "南京政府向何处去？"], "nChars": 2793, "startPage": 880}, {"id": "v4n50", "vol": 4, "title": "中共中央毛泽东主席关于时局的声明", "dateRaw": "（一九四九年一月十四日）", "y": 1949, "m": 1, "d": 14, "place": "河北西柏坡", "lat": 38.35, "lng": 113.94, "era": "解放战争时期", "why": "针对蒋介石1949年元旦求和声明及国民党假和谈阴谋，毛泽东代表中共中央发表声明，揭露国民党内战卖国罪责，并提出实现真和平必须以惩罚战犯等八项条件为基础，为即将到来的和平谈判确立方针。", "event": "三大战役", "links": ["将革命进行到底", "关于重庆谈判", "目前形势和我们的任务"], "nChars": 2770, "startPage": 883}, {"id": "v4n51", "vol": 4, "title": "中共发言人评南京行政院的决议", "dateRaw": "（一九四九年一月二十一日）", "y": 1949, "m": 1, "d": 21, "place": "河北西柏坡", "lat": 38.35, "lng": 113.94, "era": "解放战争时期", "why": "针对1949年1月19日南京行政院作出'立即先行无条件停战'的决议，中共发言人受权驳斥其既否定蒋介石元旦求和声明又拒绝中共1月14日八项和平条件建议的诡辩，揭露国民党假和平、真备战的手法。", "event": "国共和谈（三大战役后期）", "links": ["将革命进行到底", "中共中央毛泽东主席关于时局的声明", "评战犯求和"], "nChars": 1181, "startPage": 886}, {"id": "v4n52", "vol": 4, "title": "中共发言人关于命令国民党反动政府重新逮捕前日本侵华军总司令冈村宁次和逮捕国民党内战罪犯的谈话", "dateRaw": "（一九四九年一月二十八日）", "y": 1949, "m": 1, "d": 28, "place": "河北西柏坡", "lat": 38.36, "lng": 113.94, "era": "解放战争时期", "why": "1949年1月国民党政府宣称派和谈代表谋求和平，同日其军事法庭宣判日本战犯冈村宁次无罪；毛泽东以中共发言人名义发表谈话，揭露其假和谈、勾结日本法西斯的阴谋，要求重新逮捕冈村宁次并逮捕内战罪犯。", "event": "三大战役与国共和谈", "links": ["将革命进行到底", "中共中央毛泽东主席关于时局的声明", "评战犯求和"], "nChars": 4625, "startPage": 888}, {"id": "v4n53", "vol": 4, "title": "中共发言人关于和平条件必须包括惩办日本战犯和国民党战犯的声明", "dateRaw": "（一九四九年二月五日）", "y": 1949, "m": 2, "d": 5, "place": "河北西柏坡", "lat": 38.35, "lng": 113.95, "era": "解放战争时期", "why": "针对国民党政府发言人对1月28日中共声明关于惩办战犯要求的狡辩，特别是国民党军事法庭宣判冈村宁次无罪并将其连同260名日本战犯送往日本一事，中共发言人以毛泽东名义发表声明驳斥，强调惩办战犯是和平谈判的必要条件。", "event": "北平和谈", "links": ["中共中央毛泽东主席关于时局的声明", "中共发言人关于命令国民党反动政府重新逮捕前日本侵华军总司令冈村宁次和逮捕国民党内战罪犯的谈话", "把军队变为工作队"], "nChars": 2550, "startPage": 893}, {"id": "v4n54", "vol": 4, "title": "把军队变为工作队", "dateRaw": "（一九四九年二月八日）", "y": 1949, "m": 2, "d": 8, "place": "河北西柏坡", "lat": 38.3575, "lng": 113.9367, "era": "解放战争时期", "why": "三大战役胜利后，严重战争时期基本过去，为解决新解放区干部严重不足的问题，毛泽东以中央军委名义复电二野、三野，要求军队由战斗队转变为兼负工作队职能，学习接收和管理大城市。", "event": "三大战役胜利与渡江战役准备", "links": ["在中国共产党第七届中央委员会第二次全体会议上的报告", "将革命进行到底", "中国人民解放军布告"], "nChars": 1703, "startPage": 896}, {"id": "v4n55", "vol": 4, "title": "四分五裂的反动派为什么还要空喊“全面和平”？", "dateRaw": "（一九四九年二月十五日）", "y": 1949, "m": 2, "d": 15, "place": "河北西柏坡", "lat": 38.35, "lng": 113.95, "era": "解放战争时期", "why": "1949年初三大战役胜利后国民党统治总崩溃，但仍空喊'全面和平'企图阻止解放军渡江南进。毛泽东以新华社评论揭露国民党及其美国主子'和平攻势'的欺骗本质，教育人民将革命进行到底。", "event": "三大战役、蒋介石元旦文告与和平攻势", "links": ["将革命进行到底", "评战犯求和", "中国共产党第七届中央委员会第二次全体会议上的报告"], "nChars": 3330, "startPage": 898}, {"id": "v4n56", "vol": 4, "title": "国民党反动派由“呼吁和平”变为呼吁战争", "dateRaw": "（一九四九年二月十六日）", "y": 1949, "m": 2, "d": 16, "place": "河北平山县西柏坡", "lat": 38.3596, "lng": 113.9417, "era": "解放战争时期", "why": "1949年初蒋介石发动和平攻势后，国民党方面又转而反对惩办战犯、呼吁战争。毛泽东撰写此文揭露国民党假和平真战争的骗局，为新华社评论，教育人民认清其反动本质。", "event": "北平和谈前夕和平攻势", "links": ["将革命进行到底", "评战犯求和", "中共发言人关于命令国民党反动政府重新逮捕前日本侵华军总司令冈村宁次和逮捕国民党内战罪犯的谈话"], "nChars": 1452, "startPage": 902}, {"id": "v4n57", "vol": 4, "title": "评国民党对战争责任问题的几种答案", "dateRaw": "（一九四九年二月十八日）", "y": 1949, "m": 2, "d": 18, "place": "河北平山县西柏坡", "lat": 38.35, "lng": 113.94, "era": "解放战争时期", "why": "针对1949年初国民党方面在和平谈判前关于战争责任问题的多种推诿论调（蒋介石元旦声明、国民党中宣部指示、孙科广播演说等），以新华社评论逐一驳斥，揭露国民党推卸内战责任、企图逃避惩办战犯的骗局，为即将进行的北平和谈争取政治主动。", "event": "北平和谈（和平谈判）/ 战犯名单提出", "links": ["将革命进行到底", "评战犯求和", "中共中央毛泽东主席关于时局的声明"], "nChars": 4698, "startPage": 904}, {"id": "v4n58", "vol": 4, "title": "在中国共产党第七届中央委员会第二次全体会议上的报告", "dateRaw": "（一九四九年三月五日）", "y": 1949, "m": 3, "d": 5, "place": "河北西柏坡（平山县西柏坡村）", "lat": 38.35, "lng": 113.94, "era": "解放战争时期", "why": "在辽沈、淮海、平津三大战役后、全国革命胜利前夜，为七届二中全会所作的报告，解决党的工作重心由乡村转移到城市、规定胜利后政治经济外交基本政策，并警告资产阶级'糖衣炮弹'的危险。", "event": "七届二中全会", "links": ["论人民民主专政", "将革命进行到底", "在中国共产党第七届中央委员会第二次全体会议上的结论"], "nChars": 9797, "startPage": 909}, {"id": "v4n59", "vol": 4, "title": "党委会的工作方法", "dateRaw": "（一九四九年三月十三日）", "y": 1949, "m": 3, "d": 13, "place": "河北西柏坡", "lat": 38.35, "lng": 113.95, "era": "解放战争时期", "why": "本文是毛泽东在七届二中全会上所作结论的一部分。针对即将接管全国政权、各级党委领导任务日益繁重的形势，为健全党委制、改进领导工作方法而写。", "event": "七届二中全会", "links": ["关于健全党委制", "在中国共产党第七届中央委员会第二次全体会议上的报告", "关于领导方法的若干问题"], "nChars": 3069, "startPage": 919}, {"id": "v4n60", "vol": 4, "title": "南京政府向何处去？", "dateRaw": "（一九四九年四月四日）", "y": 1949, "m": 4, "d": 4, "place": "河北西柏坡", "lat": 38.35, "lng": 113.94, "era": "解放战争时期", "why": "在国共北平和谈期间，针对1949年4月1日南京惨案及李宗仁何应钦政府在和谈中的动摇敷衍，为南京国民党政府及其军政人员指明唯一出路——与蒋介石集团和美帝国主义决裂，向人民靠拢立功赎罪，配合人民解放军即将渡江南进。", "event": "北平和谈与渡江战役前夜", "links": ["将革命进行到底", "评战犯求和", "中国共产党第七届中央委员会第二次全体会议公报"], "nChars": 1902, "startPage": 922}, {"id": "v4n61", "vol": 4, "title": "向全国进军的命令", "dateRaw": "（一九四九年四月二十一日）", "y": 1949, "m": 4, "d": 21, "place": "北平", "lat": 39.9042, "lng": 116.4074, "era": "解放战争时期", "why": "1949年4月国民党反动政府拒绝签订国内和平协定，和谈破裂。毛泽东以中国人民革命军事委员会主席身份与朱德联名发布此命令，命令人民解放军向尚未解放的广大地区全面进军，消灭国民党残余势力。", "event": "渡江战役", "links": ["中国共产党第七届中央委员会第二次全体会议上的报告", "论人民民主专政", "南京政府向何处去？"], "nChars": 6869, "startPage": 924}, {"id": "v4n62", "vol": 4, "title": "中国人民解放军布告", "dateRaw": "（一九四九年四月二十五日）", "y": 1949, "m": 4, "d": 25, "place": "北平", "lat": 39.9042, "lng": 116.4074, "era": "解放战争时期", "why": "国民党政府拒绝接受《国内和平协定》后，人民解放军发起渡江战役并即将解放全国广大地区。为安定新解放区社会秩序、稳定各界人心，毛泽东以中国人民解放军名义发布约法八章，作为部队行动和接管工作的政策准则。", "event": "渡江战役", "links": ["向全国进军的命令", "在中国共产党第七届中央委员会第二次全体会议上的报告", "论人民民主专政"], "nChars": 1563, "startPage": 932}, {"id": "v4n63", "vol": 4, "title": "中国人民解放军总部发言人为英国军舰暴行发表的声明", "dateRaw": "（一九四九年四月三十日）", "y": 1949, "m": 4, "d": 30, "place": "北平", "lat": 39.9042, "lng": 116.4074, "era": "解放战争时期", "why": "针对1949年4月20日英国军舰紫石英号闯入解放军防区并向解放军开炮造成伤亡，以及丘吉尔、艾德礼扬言武力报复的言论，毛泽东为解放军总部发言人起草声明，严正表明反对帝国主义侵略、保卫领土主权的立场和新中国对外政策原则。", "event": "紫石英号事件、渡江战役", "links": ["向全国进军的命令", "中国人民解放军布告", "论人民民主专政"], "nChars": 1752, "startPage": 934}, {"id": "v4n64", "vol": 4, "title": "在新政治协商会议筹备会上的讲话", "dateRaw": "（一九四九年六月十五日）", "y": 1949, "m": 6, "d": 15, "place": "北平", "lat": 39.9042, "lng": 116.4074, "era": "解放战争时期", "why": "1949年6月新政协筹备会在北平开幕，毛泽东出席并致辞，说明筹备会的任务是迅速召开新政协、成立民主联合政府，以肃清国民党残余力量、统一全中国并开展建设，为新中国成立做政治动员。", "event": "新政治协商会议筹备会", "links": ["将革命进行到底", "在中国共产党第七届中央委员会第二次全体会议上的报告", "论人民民主专政"], "nChars": 2868, "startPage": 936}, {"id": "v4n65", "vol": 4, "title": "论人民民主专政", "dateRaw": "（一九四九年六月三十日）", "y": 1949, "m": 6, "d": 30, "place": "北平", "lat": 39.9042, "lng": 116.4074, "era": "解放战争时期", "why": "为纪念中国共产党成立二十八周年而写，系统阐述即将成立的新中国的国家政权性质——人民民主专政，回应对资产阶级共和国方案的否定，为新政协筹备和建立新中国提供理论基础。", "event": "新中国成立前夕筹备新政协", "links": ["在中国共产党第七届中央委员会第二次全体会议上的报告", "将革命进行到底", "丢掉幻想，准备斗争"], "nChars": 9630, "startPage": 939}, {"id": "v4n66", "vol": 4, "title": "丢掉幻想，准备斗争", "dateRaw": "（一九四九年八月十四日）", "y": 1949, "m": 8, "d": 14, "place": "北平", "lat": 39.9042, "lng": 116.4074, "era": "解放战争时期", "why": "1949年8月美国国务院发表中美关系白皮书及艾奇逊致杜鲁门信件，为揭露美国对华政策的帝国主义本质、批评国内部分知识分子对美国的幻想，毛泽东为新华社撰写评论。", "event": "美国发表中美关系白皮书", "links": ["别了，司徒雷登", "为什么要讨论白皮书？", "唯心历史观的破产"], "nChars": 4899, "startPage": 949}, {"id": "v4n67", "vol": 4, "title": "别了，司徒雷登", "dateRaw": "（一九四九年八月十八日）", "y": 1949, "m": 8, "d": 18, "place": "北平", "lat": 39.9042, "lng": 116.4074, "era": "解放战争时期", "why": "美国国务院于1949年8月5日发表《美中关系》白皮书，为侵华政策失败推卸责任。毛泽东撰文反驳白皮书，揭露美国侵略政策失败，批判部分知识分子对美国的幻想，为新政权做舆论准备。", "event": "美国发表美中关系白皮书", "links": ["丢掉幻想，准备斗争", "为什么要讨论白皮书", "友谊，还是侵略？"], "nChars": 5372, "startPage": 954}, {"id": "v4n68", "vol": 4, "title": "“友谊”，还是侵略？", "dateRaw": "（一九四九年八月三十日）", "y": 1949, "m": 8, "d": 30, "place": "北平", "lat": 39.9042, "lng": 116.4074, "era": "解放战争时期", "why": "批驳美国国务卿艾奇逊在美国对华政策白皮书中把侵略中国说成'友谊'的谎言，揭露美国自1840年以来尤其是通过宗教、慈善、文化事业对中国进行精神侵略的历史，教育中国人民认清美帝侵略本质。", "event": "美国发表对华政策白皮书", "links": ["别了，司徒雷登", "为什么要讨论白皮书？", "'友谊'，还是侵略？相关：丢掉幻想，准备斗争"], "nChars": 2230, "startPage": 960}, {"id": "v4n69", "vol": 4, "title": "为什么要讨论白皮书？", "dateRaw": "（一九四九年八月二十八日）", "y": 1949, "m": 8, "d": 28, "place": "北平", "lat": 39.9042, "lng": 116.4074, "era": "解放战争时期", "why": "1949年8月美国国务院发表《美国与中国的关系》白皮书及艾奇逊信件，为驳斥其对中国人民革命的诬蔑、揭穿帝国主义阴谋，毛泽东在批评白皮书的三篇文章之后，进一步号召全国各界展开对白皮书的讨论，以教育人民和民主党派中的'民主个人主义者'丢掉对美国的幻想。", "event": "美国发表中美关系白皮书", "links": ["丢掉幻想，准备斗争", "别了，司徒雷登", "“友谊”，还是侵略？"], "nChars": 3978, "startPage": 963}, {"id": "v4n70", "vol": 4, "title": "唯心历史观的破产", "dateRaw": "（一九四九年九月十六日）", "y": 1949, "m": 9, "d": 16, "place": "北平", "lat": 39.9042, "lng": 116.4074, "era": "解放战争时期", "why": "针对美国国务卿艾奇逊1949年8月发表的中美关系白皮书及信件，驳斥其以人口压力、西方影响等唯心历史观解释中国革命根源的论调，教育中国知识分子（尤其是受'民主个人主义'影响者）认清美国帝国主义实质。", "event": "美国发表《中美关系》白皮书", "links": ["别了，司徒雷登", "为什么要讨论白皮书？", "'友谊'，还是侵略？"], "nChars": 5868, "startPage": 967}, {"id": "v5n01", "vol": 5, "title": "中国人民站起来了", "dateRaw": "（一九四九年九月二十一日）", "y": 1949, "m": 9, "d": 21, "place": "北平", "lat": 39.9042, "lng": 116.4074, "era": "解放战争时期", "why": "解放战争基本胜利、国民党反动政府被打倒后，为宣告中国人民大团结和新中国即将成立，毛泽东在中国人民政治协商会议第一届全体会议开幕时致词，向全国人民和各民主党派宣告中国人从此站起来了。", "event": "中国人民政治协商会议第一届全体会议", "links": ["论人民民主专政", "在中国共产党第七届中央委员会第二次全体会议上的报告", "将革命进行到底"], "nChars": 2475, "startPage": 974}, {"id": "v5n02", "vol": 5, "title": "中国人民大团结万岁", "dateRaw": "（一九四九年九月三十日）", "y": 1949, "m": 9, "d": 30, "place": "北平", "lat": 39.9042, "lng": 116.4074, "era": "解放战争时期", "why": "这是毛泽东受中国人民政治协商会议第一届全体会议委托起草的会议宣言，为宣告中华人民共和国成立、总结全国人民大团结的历史意义并向全国同胞宣示新政府的任务而写。", "event": "中国人民政治协商会议第一届全体会议、开国大典", "links": ["论人民民主专政", "在中国共产党第七届中央委员会第二次全体会议上的报告", "唯心历史观的破产"], "nChars": 1213, "startPage": 977}, {"id": "v5n03", "vol": 5, "title": "人民英雄们永垂不朽", "dateRaw": "（一九四九年九月三十日）", "y": 1949, "m": 9, "d": 30, "place": "北平", "lat": 39.9042, "lng": 116.4074, "era": "解放战争时期", "why": "1949年9月30日中国人民政治协商会议第一届全体会议闭幕，当天举行人民英雄纪念碑奠基典礼，毛泽东为纪念碑起草碑文，纪念百年来为人民革命和民族解放牺牲的人民英雄。", "event": "中国人民政治协商会议第一届全体会议", "links": ["中国人民大团结万岁", "中华人民共和国中央人民政府公告", "论人民民主专政"], "nChars": 176, "startPage": 979}, {"id": "v5n04", "vol": 5, "title": "永远保持艰苦奋斗的作风", "dateRaw": "（一九四九年十月二十六日）", "y": 1949, "m": 10, "d": 26, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "解放战争时期", "why": "这是新中国成立后毛泽东复延安和陕甘宁边区同胞贺函的回信。为回应延安人民的祝贺并勉励全国革命工作人员，号召永远保持延安时期艰苦奋斗的作风。", "event": "中华人民共和国成立", "links": ["在中国共产党第七届中央委员会第二次全体会议上的报告", "论联合政府"], "nChars": 255, "startPage": 980}, {"id": "v5n05", "vol": 5, "title": "征询对待富农策略问题的意见", "dateRaw": "（一九五○年三月十二日）", "y": 1950, "m": 3, "d": 12, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "新中国即将在南方各省及西北部分地区开展大规模土地改革，毛泽东就暂时不动富农（包括半封建富农）的策略问题征询各中央局意见，以便修改土地法、统一干部认识，避免土改中出现过左偏向并稳定民族资产阶级。", "event": "新区土地改革", "links": ["在中国共产党第七届中央委员会第二次全体会议上的报告", "论人民民主专政", "为争取国家财政经济状况的基本好转而斗争"], "nChars": 717, "startPage": 981}, {"id": "v5n06", "vol": 5, "title": "为争取国家财政经济状况的基本好转而斗争", "dateRaw": "(一九五○年六月六日)", "y": 1950, "m": 6, "d": 6, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "这是毛泽东在七届三中全会上的书面报告。新中国成立不久，财政经济困难、通货膨胀尚未完全制止，加上土匪特务破坏和朝鲜战争阴云，需要向全党阐明争取国家财政经济状况基本好转的三个条件和策略方针，团结民族资产阶级和各界人士，不要四面出击。", "event": "中共七届三中全会", "links": ["在中国共产党第七届中央委员会第二次全体会议上的报告", "论人民民主专政", "不要四面出击"], "nChars": 3930, "startPage": 982}, {"id": "v5n07", "vol": 5, "title": "不要四面出击", "dateRaw": "(一九五○年六月六日)", "y": 1950, "m": 6, "d": 6, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "新中国成立初期财政经济困难、社会各阶层对社会经济改组不满，毛泽东在七届三中全会上说明书面报告的战略策略思想，告诫全党不可树敌太多，要集中力量孤立和打击主要敌人，团结大多数以争取财政经济状况基本好转。", "event": "中共七届三中全会", "links": ["为争取国家财政经济状况的基本好转而斗争", "在中国共产党第七届中央委员会第二次全体会议上的报告", "论人民民主专政"], "nChars": 2111, "startPage": 986}, {"id": "v5n08", "vol": 5, "title": "做一个完全的革命派", "dateRaw": "(一九五○年六月二十三日)", "y": 1950, "m": 6, "d": 23, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "全国政协一届二次会议中心议题是土地改革，毛泽东在闭幕词中号召各民主党派、民主人士团结一致，做完全的革命派，支持和参与土改，巩固人民民主统一战线。", "event": "土地改革运动、政协一届二次会议", "links": ["在中国共产党第七届中央委员会第二次全体会议上的报告", "论人民民主专政", "为争取国家财政经济状况的基本好转而斗争"], "nChars": 2798, "startPage": 989}, {"id": "v5n09", "vol": 5, "title": "你们是全民族的模范人物", "dateRaw": "(一九五○年九月二十五日)", "y": 1950, "m": 9, "d": 25, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "新中国成立一周年国庆前夕，中共中央召开全国战斗英雄代表会议和全国工农兵劳动模范代表会议，毛泽东代表中共中央致祝词，表彰模范人物并号召全党全国向他们学习，强调建设强大国防军和经济力量两件大事。", "event": "全国战斗英雄代表会议和全国工农兵劳动模范代表会议", "links": ["《中国人民站起来了》", "《为争取国家财政经济状况的基本好转而斗争》"], "nChars": 611, "startPage": 992}, {"id": "v5n10", "vol": 5, "title": "给中国人民志愿军的命令", "dateRaw": "(一九五○年十月八日)", "y": 1950, "m": 10, "d": 8, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "朝鲜战争爆发、美军越过三八线并逼近平壤后，中共中央作出抗美援朝决策，毛泽东以中央军委主席名义发布命令，将东北边防军改为中国人民志愿军入朝作战，并就纪律和克服困难作出指示。", "event": "抗美援朝", "links": ["抗美援朝的伟大胜利和今后的任务", "中国人民志愿军要爱护朝鲜的一山一水一草一木"], "nChars": 448, "startPage": 993}, {"id": "v5n11", "vol": 5, "title": "中国人民志愿军要爱护朝鲜的一山一水一草一木", "dateRaw": "(一九五一年一月十九日)", "y": 1951, "m": 1, "d": 19, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "抗美援朝战争进行中，志愿军入朝作战已数月，毛泽东为加强中朝团结、严明志愿军纪律、奠定胜利的政治基础，向中国人民志愿军下达此指示。", "event": "抗美援朝战争", "links": ["组成中国人民志愿军的命令", "给中国人民志愿军的命令", "关于和平谈判时期的策略"], "nChars": 206, "startPage": 994}, {"id": "v5n12", "vol": 5, "title": "中共中央政治局扩大会议决议要点", "dateRaw": "(一九五一年二月十八日)", "y": 1951, "m": 2, "d": 18, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "1951年2月中央政治局扩大会议后，毛泽东为中共中央起草党内通报，向各地负责人传达'三年准备、十年计划经济建设'的部署，统一抗美援朝宣传、土改、镇反、城市工作和整党等各项工作的方针与节奏。", "event": "抗美援朝、土地改革运动、镇压反革命运动", "links": ["在中国共产党第七届中央委员会第二次全体会议上的报告", "为争取国家财政经济状况的基本好转而斗争", "关于镇压反革命活动的指示"], "nChars": 1946, "startPage": 995}, {"id": "v5n13", "vol": 5, "title": "镇压反革命必须实行党的群众路线", "dateRaw": "(一九五一年五月十五日)", "y": 1951, "m": 5, "d": 15, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "为修改第三次全国公安会议决议而写的指示，针对镇压反革命运动中可能出现的草率从事和'左'的偏向，强调必须实行党的群众路线，严格控制捕人杀人数字和批准权限。", "event": "镇压反革命运动", "links": ["关于镇压反革命活动的指示", "中共中央关于土改与镇反工作的指示"], "nChars": 1440, "startPage": 998}, {"id": "v5n14", "vol": 5, "title": "镇压反革命必须打得稳，打得准，打得狠", "dateRaw": "（一九五○年十二月十九日）", "y": 1950, "m": 12, "d": 19, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "新中国成立初期残余反革命分子破坏活动猖獗，毛泽东为中共中央起草一系列指示，部署镇压反革命运动，强调打得稳、打得准、打得狠，防止错捕错杀并提出死缓等慎重政策。", "event": "镇压反革命运动", "links": ["不要四面出击", "关于镇压反革命", "中共中央关于镇压反革命活动的指示"], "nChars": 1698, "startPage": 1000}, {"id": "v5n15", "vol": 5, "title": "应当重视电影《武训传》的讨论", "dateRaw": "(一九五一年五月二十日)", "y": 1951, "m": 5, "d": 20, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "电影《武训传》上映后受到广泛歌颂，毛泽东认为这暴露了文化界乃至党内思想混乱、资产阶级反动思想侵蚀的问题，故为《人民日报》撰写社论，发动对该片的批判讨论，以澄清历史唯物主义的立场。", "event": "批判电影《武训传》运动", "links": ["在延安文艺座谈会上的讲话", "丢掉幻想，准备斗争", "唯心历史观的破产"], "nChars": 980, "startPage": 1002}, {"id": "v5n16", "vol": 5, "title": "三大运动的伟大胜利", "dateRaw": "（一九五一年十月二十三日）", "y": 1951, "m": 10, "d": 23, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "在全国政协一届三次会议开会词中总结抗美援朝、土地改革、镇压反革命三大运动的胜利，动员全国人民继续增产节约、加强国防和经济建设。", "event": "抗美援朝运动、土地改革、镇压反革命", "links": ["中国人民站起来了", "为争取国家财政经济状况的基本好转而斗争", "给中国人民志愿军的命令"], "nChars": 2892, "startPage": 1003}, {"id": "v5n17", "vol": 5, "title": "关于“三反”、“五反”的斗争", "dateRaw": "(一九五一年十一月三十日)", "y": 1951, "m": 11, "d": 30, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "新中国成立后，部分党政干部发生贪污、浪费和官僚主义问题，并受资产阶级腐蚀。为贯彻中共七届二中全会关于防止腐蚀的方针，中央发动“三反”并继而开展“五反”斗争。", "event": "三反五反运动", "links": ["在中国共产党第七届中央委员会第二次全体会议上的报告"], "nChars": 3069, "startPage": 1006}, {"id": "v5n18", "vol": 5, "title": "把农业互助合作当作一件大事去做", "dateRaw": "(一九五一年十二月十五日)", "y": 1951, "m": 12, "d": 15, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "为印发《中共中央关于农业生产互助合作的决议（草案）》起草党内通知，批驳刘少奇反对农业合作化的意见，要求各级党委在已完成土地改革的地区把农业互助合作当作一件大事去解释和实行。", "event": "农业互助合作运动", "links": ["关于农业合作化问题", "组织起来", "中国农村的社会主义高潮》的序言"], "nChars": 523, "startPage": 1010}, {"id": "v5n19", "vol": 5, "title": "元旦祝词", "dateRaw": "(一九五二年一月一日)", "y": 1952, "m": 1, "d": 1, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "1952年元旦之际，毛泽东总结1951年抗美援朝、土地改革、镇反、经济财政等各条战线的胜利，并向全国发出开展'三反'（反贪污、反浪费、反官僚主义）运动的号召，动员全国人民争取1952年更大胜利。", "event": "三反运动、抗美援朝", "links": ["中国人民志愿军要爱护朝鲜的一山一水一草一木", "迎接中国革命的新高潮"], "nChars": 414, "startPage": 1011}, {"id": "v5n20", "vol": 5, "title": "中共中央关于西藏工作方针的指示", "dateRaw": "(一九五二年四月六日)", "y": 1952, "m": 4, "d": 6, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "1951年西藏和平解放后，进藏部队面临物资匮乏、民族关系复杂和上层集团动摇等问题。毛泽东为中央起草此指示，肯定西南局方针，确立'精打细算、生产自给'和打通贸易两条基本政策，以争取达赖及上层集团多数、稳步经营西藏。", "event": "西藏和平解放", "links": ["关于西藏和平解放的办法的协议", "中国人民站起来了", "为争取国家财政经济状况的基本好转而斗争"], "nChars": 2167, "startPage": 1012}, {"id": "v5n21", "vol": 5, "title": "工人阶级与资产阶级的矛盾是国内的主要矛盾", "dateRaw": "(一九五二年六月六日)", "y": 1952, "m": 6, "d": 6, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "针对中央统战部文件负责人仍把民族资产阶级视为中间阶级的错误观点，毛泽东批语指出土改和推翻官僚资产阶级后国内主要矛盾已转为工人阶级与民族资产阶级的矛盾。", "event": "土地改革基本完成、三反五反运动", "links": ["目前时局和我们的任务", "在中国共产党第七届中央委员会第二次全体会议上的报告", "为争取国家财政经济状况的基本好转而斗争"], "nChars": 246, "startPage": 1015}, {"id": "v5n22", "vol": 5, "title": "团结起来，划清敌我界限", "dateRaw": "（一九五二年八月四日）", "y": 1952, "m": 8, "d": 4, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "在抗美援朝边打边谈、国内三反五反运动胜利结束的背景下，向政协常委会通报形势，号召团结起来、划清敌我界限，巩固人民民主统一战线。", "event": "抗美援朝运动、三反五反运动", "links": ["为争取国家财政经济状况的基本好转而斗争", "中国人民站起来了", "不要四面出击"], "nChars": 1787, "startPage": 1016}, {"id": "v5n23", "vol": 5, "title": "祝贺中国人民志愿军的重大胜利", "dateRaw": "(一九五二年十月二十四日)", "y": 1952, "m": 10, "d": 24, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "1952年10月志愿军全线战术反击取得歼敌三万以上的重大胜利，毛泽东为中共中央和中央军委起草指示，嘉奖志愿军并总结'零敲牛皮糖'式阵地战术反击经验，以迫使敌人妥协结束朝鲜战争。", "event": "抗美援朝战争秋季战术反击作战", "links": ["给中国人民志愿军的命令", "关于派志愿军入朝参战的电报（如选入）", "抗美援朝的伟大胜利和今后的任务"], "nChars": 696, "startPage": 1019}, {"id": "v5n24", "vol": 5, "title": "反对官僚主义、命令主义和违法乱纪", "dateRaw": "(一九五三年一月五日)", "y": 1953, "m": 1, "d": 5, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "“三反”运动后，毛发现中央和省市级的贪污浪费问题基本解决，但县区乡三级干部中的命令主义、违法乱纪及上级机关的官僚主义（如积压人民来信）仍严重存在，故为中央起草此党内指示，部署开展“新三反”斗争。", "event": "三反运动及随后的新三反斗争", "links": ["关于“三反”“五反”的斗争", "反对党八股", "必须学会做经济工作"], "nChars": 1296, "startPage": 1020}, {"id": "v5n25", "vol": 5, "title": "批判大汉族主义", "dateRaw": "(一九五三年三月十六日)", "y": 1953, "m": 3, "d": 16, "place": "北京", "lat": 39.9042, "lng": 116.407, "era": "社会主义革命和建设时期", "why": "针对建国初期部分地区民族关系不正常、党内许多党员和干部存在严重大汉族主义思想的问题，毛泽东为中共中央起草党内指示，要求批评教育并派访问团调查研究、解决少数民族问题。", "event": "民族政策检查与民族访问团活动", "links": ["关于正确处理人民内部矛盾的问题", "论十大关系"], "nChars": 719, "startPage": 1022}, {"id": "v5n26", "vol": 5, "title": "解决“五多”问题", "dateRaw": "(一九五三年三月十九日)", "y": 1953, "m": 3, "d": 19, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "针对建国初期农村党政工作中严重脱离群众的'五多'问题（任务多、会议多、公文多、组织多、兼职多），毛泽东为中共中央起草党内指示，要求各级领导机关克服分散主义和官僚主义，并为配合1953年1月反官僚主义指示的执行而系统解决此问题。", "event": "新中国成立初期农村整风与反官僚主义运动", "links": ["反对官僚主义、命令主义和违法乱纪", "关于'三反''五反'的斗争", "批判大汉族主义"], "nChars": 1545, "startPage": 1023}, {"id": "v5n27", "vol": 5, "title": "对刘少奇、杨尚昆破坏纪律擅自以中央名义发出文件的批评", "dateRaw": "（一九五三年五月十九日）", "y": 1953, "m": 5, "d": 19, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "毛泽东发现刘少奇、杨尚昆未经其审阅即以中央名义发出文件、电报和会议决议，认为这破坏了党内纪律，故提出书面批评，要求嗣后凡用中央名义发出的文件必须经他看过方能发出。", "event": "建国后加强中央文书纪律（1953年）", "links": ["反对党内的资产阶级思想", "增强党的团结，继承党的传统"], "nChars": 240, "startPage": 1025}, {"id": "v5n28", "vol": 5, "title": "批判离开总路线的右倾观点", "dateRaw": "（一九五三年六月十五日）", "y": 1953, "m": 6, "d": 15, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "1953年6月15日中共中央政治局会议上，毛泽东为统一党内认识、批判刘少奇等人'确立新民主主义社会秩序''确保私有财产'等右倾观点而作，旨在确立党在过渡时期总路线的指导地位。", "event": "过渡时期总路线的提出", "links": ["党在过渡时期的总路线", "关于国家资本主义经济", "关于农业合作化问题"], "nChars": 1063, "startPage": 1026}, {"id": "v5n29", "vol": 5, "title": "青年团的工作要照顾青年的特点", "dateRaw": "(一九五三年六月三十日)", "y": 1953, "m": 6, "d": 30, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "1953年6月30日毛泽东接见中国新民主主义青年团第二次全国代表大会主席团时的谈话，针对青年团工作缺乏独立活动、不够照顾青年特点的问题，指出团要围绕党的中心任务开展适合青年的独立工作，并关心青年身体、学习和工作负担。", "event": "青年团二大", "links": ["为争取国家财政经济状况的基本好转而斗争", "关于国家资本主义经济", "反对党内的资产阶级思想"], "nChars": 3117, "startPage": 1028}, {"id": "v5n30", "vol": 5, "title": "关于国家资本主义", "dateRaw": "（一九五三年七月九日）", "y": 1953, "m": 7, "d": 9, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "1953年党提出过渡时期总路线、开始对资本主义工商业进行社会主义改造，此文是在全国财经工作会议文件上的批语，为回应对私营工商业改造的疑虑，论证国家资本主义经济具有社会主义性质、对工人和国家有利。", "event": "1953年夏季全国财经工作会议、过渡时期总路线", "links": ["关于国家资本主义经济和合作社经济", "关于党在过渡时期的总路线", "关于农业合作化问题"], "nChars": 356, "startPage": 1031}, {"id": "v5n31", "vol": 5, "title": "党在过渡时期的总路线", "dateRaw": "（一九五三年八月）", "y": 1953, "m": 8, "d": 1, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "毛泽东在审阅周恩来1953年夏季全国财经工作会议结论时作出批示，针对党内一些同志不遵照七届二中全会规定、偏离过渡时期方针的问题，系统阐明党在过渡时期的总路线，以统一全党思想。", "event": "1953年夏季全国财经工作会议", "links": ["在中国共产党第七届中央委员会第二次全体会议上的报告"], "nChars": 326, "startPage": 1032}, {"id": "v5n32", "vol": 5, "title": "反对党内的资产阶级思想", "dateRaw": "（一九五三年八月十二日）", "y": 1953, "m": 8, "d": 12, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "1953年夏季全国财经工作会议上批评薄一波'公私一律平等'新税制错误，针对财经工作中暴露的资产阶级思想倾向，为确立和贯彻党在过渡时期的总路线、统一党内思想而作。", "event": "全国财经工作会议、新税制争论、过渡时期总路线提出", "links": ["为争取国家财政经济状况的基本好转而斗争", "关于'三反''五反'的斗争", "党在过渡时期的总路线"], "nChars": 5043, "startPage": 1033}, {"id": "v5n33", "vol": 5, "title": "改造资本主义工商业的必经之路", "dateRaw": "(一九五三年九月七日)", "y": 1953, "m": 9, "d": 7, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "1953年过渡时期总路线提出后，为统一党内和民主党派、工商界代表对私营工商业社会主义改造方针的认识，毛泽东强调经国家资本主义逐步改造资本主义工商业是必经之路，以消除资本家疑虑并防止急于求成。", "event": "过渡时期总路线与私营工商业社会主义改造", "links": ["关于国家资本主义经济", "关于党在过渡时期的总路线", "论人民民主专政"], "nChars": 1605, "startPage": 1039}, {"id": "v5n34", "vol": 5, "title": "抗美援朝的伟大胜利和今后的任务", "dateRaw": "（一九五三年九月十二日）", "y": 1953, "m": 9, "d": 12, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "抗美援朝战争于1953年7月停战后，毛泽东在中央人民政府委员会第二十四次会议上总结战争胜利的原因和经验，并阐述今后的任务，回应国内对战争代价与前途的关切。", "event": "抗美援朝战争停战", "links": ["组成中国人民志愿军的命令", "中国人民志愿军要爱护朝鲜的一山一水一草一木"], "nChars": 3198, "startPage": 1041}, {"id": "v5n35", "vol": 5, "title": "关于农业互助合作的两次谈话", "dateRaw": "（一九五三年十月十五日、十一月四日）", "y": 1953, "m": 10, "d": 15, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "在第三次农业互助合作会议前后，同中央农村工作部负责人谈话，纠正互助合作运动中的右倾保守倾向，部署发展农业生产合作社，贯彻党在过渡时期的总路线。", "event": "第三次农业互助合作会议", "links": ["关于农业合作化问题", "党在过渡时期的总路线", "关于国家资本主义经济"], "nChars": 5422, "startPage": 1045}, {"id": "v5n36", "vol": 5, "title": "关于中华人民共和国宪法草案", "dateRaw": "（一九五四年六月十四日）", "y": 1954, "m": 6, "d": 14, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "1954年宪法草案起草完成后，毛泽东在中央人民政府委员会会议上讲话，说明草案经过全国八千多人广泛讨论得以完善，阐明'领导意见与群众意见相结合'的立法方法，为宪法草案的通过和随后全民讨论、全国人大召开作准备。", "event": "1954年宪法起草", "links": ["论人民民主专政", "为建设一个伟大的社会主义国家而奋斗"], "nChars": 4457, "startPage": 1051}, {"id": "v5n37", "vol": 5, "title": "为建设一个伟大的社会主义国家而奋斗", "dateRaw": "(一九五四年九月十五日)", "y": 1954, "m": 9, "d": 15, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "这是毛泽东在第一届全国人民代表大会第一次会议上的开幕词，为新中国首部宪法的制定和国家领导机构的选举而作，向全国人民阐明建设伟大社会主义国家的总任务。", "event": "第一届全国人民代表大会第一次会议", "links": ["中国人民站起来了", "为争取国家财政经济状况的基本好转而斗争", "关于国家资本主义经济"], "nChars": 920, "startPage": 1056}, {"id": "v5n38", "vol": 5, "title": "关于《红楼梦》研究问题的信", "dateRaw": "(一九五四年十月十六日)", "y": 1954, "m": 10, "d": 16, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "针对李希凡、蓝翎两个青年批判俞平伯《红楼梦》研究的文章在《文艺报》《人民日报》受压制一事，写信给政治局同志，发动对胡适派资产阶级唯心论的批判，并批评党内'大人物'阻拦小人物批评的投降主义倾向。", "event": "批判《红楼梦》研究与胡适唯心论运动", "links": ["应当重视电影〈武训传〉的讨论"], "nChars": 943, "startPage": 1058}, {"id": "v5n39", "vol": 5, "title": "原子弹吓不倒中国人民", "dateRaw": "（一九五五年一月二十八日）", "y": 1955, "m": 1, "d": 28, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "毛泽东在会见芬兰首任驻华大使递交国书时发表谈话，针对美国侵占台湾海峡并进行原子讹诈的威胁，表明中国人民不惧核威慑、坚决反击侵略的立场。", "event": "抗美援朝战争后中美对峙与台湾问题", "links": ["抗美援朝的伟大胜利和今后的任务", "别了，司徒雷登", "关于和平共处五项原则的谈话"], "nChars": 929, "startPage": 1059}, {"id": "v5n40", "vol": 5, "title": "驳“舆论一律”", "dateRaw": "（一九五五年五月二十四日）", "y": 1955, "m": 5, "d": 24, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "1955年胡风反革命集团案被揭露后，胡风等人以“舆论一律”指责新政权压制言论自由，毛泽东写此文予以反驳，阐明人民内部民主与对反革命专政相区别的理论。", "event": "批判胡风反革命集团", "links": ["关于胡风反革命集团的材料按语和序言", "论人民民主专政", "关于正确处理人民内部矛盾的问题"], "nChars": 1858, "startPage": 1060}, {"id": "v5n41", "vol": 5, "title": "关于农业合作化问题", "dateRaw": "(一九五五年七月三十一日)", "y": 1955, "m": 7, "d": 31, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "1955年农业合作化运动加速之际，党内部分同志对合作社发展速度持保守犹豫态度，毛泽东在省市自治区党委书记会议上作此报告，批评'小脚女人'式的右倾保守思想，号召积极领导即将到来的农村社会主义群众运动高潮。", "event": "农业合作化运动", "links": ["关于农业合作化问题的决议草案的说明", "中国农村的社会主义高潮", "论十大关系"], "nChars": 14820, "startPage": 1062}, {"id": "v5n42", "vol": 5, "title": "农业合作化必须依靠党团员和贫农下中农", "dateRaw": "(一九五五年九月七日)", "y": 1955, "m": 9, "d": 7, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "1955年农业合作化高潮兴起之际，针对各地强迫富裕中农入社、侵犯其利益等违反团结中农原则的问题，毛泽东为中共中央起草党内指示，明确合作社应依靠党团员、贫农和下中农，按阶级成分和觉悟程度分批吸收入社。", "event": "农业合作化运动", "links": ["关于农业合作化问题", "农业合作化的一场辩论和当前的阶级斗争", "中国农村的社会主义高潮"], "nChars": 1318, "startPage": 1077}, {"id": "v5n43", "vol": 5, "title": "农业合作化的一场辩论和当前的阶级斗争", "dateRaw": "（一九五五年十月十一日）", "y": 1955, "m": 10, "d": 11, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "这是毛泽东在七届六中全会（扩大）上作的结论，回应党内围绕农业合作化速度问题的激烈争论，批判“右倾保守”思想，论证总路线的正确性，并为加速农业社会主义改造和资本主义工商业改造作动员。", "event": "农业合作化运动、七届六中全会（扩大）", "links": ["关于农业合作化问题", "中国农村的社会主义高潮》的序言", "关于资本主义工商业社会主义改造问题"], "nChars": 14407, "startPage": 1079}, {"id": "v5n44", "vol": 5, "title": "征询对农业十七条的意见", "dateRaw": "(一九五五年十二月二十一日)", "y": 1955, "m": 12, "d": 21, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "1955年农业合作化高潮中，毛泽东在杭州、天津与省委书记商定农业十七条后，为中共中央起草通知征询各中央局、省委意见，以便在1956年1月中央会议上确定并纳入1956年计划实行。", "event": "农业合作化运动", "links": ["关于农业合作化问题", "农业合作化的一场辩论和当前的阶级斗争", "中国农村的社会主义高潮"], "nChars": 2061, "startPage": 1094}, {"id": "v5n45", "vol": 5, "title": "加快手工业的社会主义改造", "dateRaw": "(一九五六年三月四日)", "y": 1956, "m": 3, "d": 4, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "1956年社会主义改造进入高潮，毛泽东听取国务院有关部门手工业工作汇报时，针对手工业合作化速度偏慢、撤点过多引起群众不满等问题作出指示，要求加快改造并保护传统手工艺和民间艺人。", "event": "手工业社会主义改造高潮", "links": ["关于农业合作化问题", "中国农村的社会主义高潮的序言和按语"], "nChars": 1509, "startPage": 1097}, {"id": "v5n46", "vol": 5, "title": "美帝国主义是纸老虎", "dateRaw": "(一九五六年七月十四日)", "y": 1956, "m": 7, "d": 14, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "1956年7月毛泽东接见两位拉丁美洲人士时，针对美国在全球打着反共旗号进行侵略扩张、压迫亚非拉民族的现象，阐述'一切反动派都是纸老虎'、新生力量必然战胜腐朽力量的观点，以鼓励被压迫民族的独立斗争。", "event": "会见拉丁美洲人士（苏伊士危机前夜的中拉友好交流背景）", "links": ["和美国记者安娜·路易斯·斯特朗的谈话", "一切反动派都是纸老虎", "论人民民主专政"], "nChars": 2346, "startPage": 1099}, {"id": "v5n47", "vol": 5, "title": "增强党的团结，继承党的传统", "dateRaw": "(一九五六年八月三十日)", "y": 1956, "m": 8, "d": 30, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "在中共八大预备会议第一次会议上，为总结七大以来十一年经验、增强党的团结、准备召开八大而作，回应党内外的疑虑并动员全党为建设社会主义中国而奋斗。", "event": "中共八大预备会议", "links": ["《论联合政府》", "《在中国共产党第七届中央委员会第二次全体会议上的报告》", "《为争取国家财政经济状况的基本好转而斗争》"], "nChars": 7924, "startPage": 1102}, {"id": "v5n48", "vol": 5, "title": "我们党的—些历史经验", "dateRaw": "(一九五六年九月二十五日)", "y": 1956, "m": 9, "d": 25, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "中共八大期间，毛泽东同拉丁美洲一些党的代表谈话，向他们介绍中国共产党领导农民革命和统一战线等方面的历史经验，帮助受帝国主义、封建主义压迫的国家政党认识农村工作和农民同盟军的重要性。", "event": "中共八大", "links": ["中国社会各阶级的分析", "论联合政府", "在中国共产党第七届中央委员会第二次全体会议上的报告"], "nChars": 3824, "startPage": 1110}, {"id": "v5n49", "vol": 5, "title": "纪念孙中山先生", "dateRaw": "(一九五六年十一月十二日)", "y": 1956, "m": 11, "d": 12, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "为纪念孙中山诞辰九十周年而写，旨在肯定孙中山作为革命先行者的历史功绩，阐明中国共产党是孙中山革命事业的继承者，并告诫国人要谦虚、反对大国主义。", "event": "纪念孙中山诞辰九十周年", "links": ["论人民民主专政", "中国人民站起来了", "唯心历史观的破产"], "nChars": 757, "startPage": 1114}, {"id": "v5n50", "vol": 5, "title": "在中国共产党第八届中央委员会第二次全体会议上的讲话", "dateRaw": "（一九五六年十一月十五日）", "y": 1956, "m": 11, "d": 15, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "1956年波匈事件和苏共二十大批判斯大林后，国际共产主义运动出现动荡，国内一五计划建设和社会主义改造中也出现进退、平衡与不平衡等争论。毛泽东在八届二中全会上就经济问题、国际形势、中苏关系和大民主小民主问题讲话，旨在统一党内认识、辩证看待计划的进退波浪式前进。", "event": "中共八届二中全会", "links": ["论十大关系", "关于正确处理人民内部矛盾的问题"], "nChars": 10801, "startPage": 1115}, {"id": "v5n51", "vol": 5, "title": "在中国共产党全国宣传工作会议上的讲话", "dateRaw": "一九五七年三月十二日", "y": 1957, "m": 3, "d": 12, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "1957年社会主义改造基本完成后，为回应知识分子问题和思想界在新社会制度下的各种反应，毛泽东在全国宣传工作会议上阐述社会大变动时期的意识形态斗争和知识分子政策，为随后的整风和思想战线上的社会主义教育作思想准备。", "event": "社会主义改造基本完成、整风运动前夕", "links": ["关于正确处理人民内部矛盾的问题", "论十大关系", "事情正在起变化"], "nChars": 10406, "startPage": 1126}, {"id": "v5n52", "vol": 5, "title": "中国共产党是全中国人民的领导核心", "dateRaw": "（一九五七年五月二十五日）", "y": 1957, "m": 5, "d": 25, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "1957年5月接见中国新民主主义青年团第三次全国代表大会全体代表时即席讲话，针对当时整风反右前后出现的离开社会主义的言论倾向，强调党的领导核心地位，号召青年团结起来为社会主义事业奋斗。", "event": "中国新民主主义青年团第三次全国代表大会", "links": ["关于正确处理人民内部矛盾的问题", "在中国共产党全国宣传工作会议上的讲话", "事情正在起变化"], "nChars": 235, "startPage": 1136}, {"id": "v5n53", "vol": 5, "title": "组织力量反击右派分子的猖狂进攻", "dateRaw": "（一九五七年六月八日）", "y": 1957, "m": 6, "d": 8, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "1957年整风运动中，党外鸣放出现批评浪潮，毛泽东判断右派分子向党和新政权猖狂进攻，故起草此党内指示，部署组织力量反击右派，以掌握主动、教育群众、孤立反对派。", "event": "反右派运动", "links": ["关于正确处理人民内部矛盾的问题", "事情正在起变化", "一九五七年夏季的形势"], "nChars": 1327, "startPage": 1137}, {"id": "v5n54", "vol": 5, "title": "文汇报的资产阶级方向应当批判", "dateRaw": "（一九五七年七月一日）", "y": 1957, "m": 7, "d": 1, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "1957年整风运动中出现大鸣大放，毛泽东认定文汇报、光明日报等被资产阶级右派（章伯钧、罗隆基等）利用进行反共反社会主义宣传，故为《人民日报》撰写社论，推动反右派斗争的深入并指导报界转向社会主义方向。", "event": "反右派斗争", "links": ["关于正确处理人民内部矛盾的问题", "事情正在起变化", "组织力量反击右派分子的猖狂进攻"], "nChars": 3376, "startPage": 1139}, {"id": "v5n55", "vol": 5, "title": "一九五七年夏季的形势", "dateRaw": "（一九五七年七月）", "y": 1957, "m": 7, "d": 1, "place": "山东青岛", "lat": 36.0671, "lng": 120.3826, "era": "社会主义革命和建设时期", "why": "在1957年整风运动转向后，针对资产阶级右派向党和社会主义制度进攻的问题，毛泽东在青岛省市委书记会议上发文部署反右派斗争和全国整风，论述正确处理人民内部矛盾与敌我矛盾。", "event": "反右派斗争、青岛省市委书记会议", "links": ["关于正确处理人民内部矛盾的问题", "事情正在起变化", "组织力量反击右派分子的猖狂进攻"], "nChars": 6018, "startPage": 1143}, {"id": "v5n56", "vol": 5, "title": "坚定地相信群众的大多数", "dateRaw": "（一九五七年十月十三日）", "y": 1957, "m": 10, "d": 13, "place": "北京", "lat": 39.9042, "lng": 116.4074, "era": "社会主义革命和建设时期", "why": "1957年整风和反右运动中，毛泽东在最高国务会议上阐释大鸣、大放、大辩论、大字报这一群众创造的新形式，针对党内和干部中'怕乱、怕下不得台'的顾虑，强调要相信群众的大多数，为推进社会主义教育和反右斗争提供依据。", "event": "整风运动和反右斗争", "links": ["关于正确处理人民内部矛盾的问题", "事情正在起变化", "组织力量反击右派分子的猖狂进攻"], "nChars": 10100, "startPage": 1149}, {"id": "v5n57", "vol": 5, "title": "党内团结的辩证方法", "dateRaw": "（一九五七年十一月十八日）", "y": 1957, "m": 11, "d": 18, "place": "苏联莫斯科", "lat": 55.7558, "lng": 37.6173, "era": "社会主义革命和建设时期", "why": "1957年11月毛泽东赴莫斯科参加十月革命四十周年庆典并出席共产党和工人党代表会议，针对国际共产主义运动和党内如何对待犯错误同志的问题，阐述团结的辩证方法，既斗争又帮助，为各国党处理内部关系提供方法论。", "event": "莫斯科共产党和工人党代表会议", "links": ["关于正确处理人民内部矛盾的问题", "论十大关系", "增强党的团结，继承党的传统"], "nChars": 1847, "startPage": 1159}, {"id": "v5n58", "vol": 5, "title": "一切反动派都是纸老虎", "dateRaw": "（一九五七年十一月十八日）", "y": 1957, "m": 11, "d": 18, "place": "苏联莫斯科", "lat": 55.7558, "lng": 37.6173, "era": "社会主义革命和建设时期", "why": "1957年11月毛泽东率中共代表团出席莫斯科共产党和工人党代表会议，在会议发言中重申1946年对安娜·路易斯·斯特朗提出的'一切反动派都是纸老虎'论断，鼓舞社会主义阵营正视帝国主义和原子弹威胁，阐明战略上藐视敌人、战术上重视敌人的斗争方法。", "event": "莫斯科共产党和工人党代表会议", "links": ["和美国记者安娜·路易斯·斯特朗的谈话", "目前形势和我们的任务", "关于重庆谈判"], "nChars": 4259, "startPage": 1161}];
const PLACE_BG={"广东广州": "1925年广州是国民革命的中心，孙中山领导的国民政府在此成立，国共两党实现第一次合作。毛泽东此时在广州担任国民党中央宣传部代理部长，并主办第六届农民运动讲习所。", "湖南长沙": "1927年初，北伐战争推进至长江流域，湖南农民运动迅猛发展，成为全国农民运动的中心。毛泽东此时回到湖南实地考察湘潭、湘乡等五县农民运动状况。", "江西井冈山": "1927年大革命失败后，毛泽东率秋收起义部队于同年10月到达井冈山，创建了中国第一个农村革命根据地，开辟了工农武装割据的道路。1928年4月朱毛会师，根据地武装力量进一步壮大。", "福建上杭县古田": "1929年红四军转战赣南闽西，开辟了闽西革命根据地。同年12月红四军党的第九次代表大会（古田会议）在古田召开，确立了思想建党、政治建军的原则。", "江西寻乌": "1930年毛泽东利用红四军短暂分兵发动群众之机，在寻乌进行了大规模社会调查，为反对教条主义、倡导调查研究作风提供了实践基础。", "江西瑞金": "1931年11月中华苏维埃共和国临时中央政府在瑞金成立，瑞金成为红色首都。1933-1934年中央苏区进行经济建设并经历第五次反“围剿”斗争，1934年10月中央红军被迫开始长征。", "陕北子长县瓦窑堡（今陕西子长市瓦窑堡镇）": "1935年10月中央红军长征到达陕北，11月中共中央进驻瓦窑堡。同年12月召开瓦窑堡会议，确定了建立抗日民族统一战线的策略方针。", "陕北保安（今陕西志丹县）": "1936年7月至12月，保安是中共中央所在地。此间红军东征回师后西征扩大陕甘宁根据地，12月发生西安事变，促成国共第二次合作的初步形成。", "陕西延安": "1937年1月至1947年3月，延安是中共中央所在地，是抗日战争的指挥中心和敌后战场的神经中枢。此间开展了整风运动和大生产运动，延安成为革命圣地和进步青年向往之地。", "陕北洛川": "1937年8月，中共中央在洛川召开政治局扩大会议，通过《抗日救国十大纲领》，确定了我党全面抗战路线和敌后游击战的战略方针。", "陕北延安": "1937-1941年间延安作为中共中央所在地，领导八路军、新四军开辟敌后战场。1941年苏德战争爆发后，中共中央提出建立国际反法西斯统一战线的主张。", "陕甘宁边区延安（陕西延安）": "1941年陕甘宁边区是抗日根据地的模范区，实行“三三制”政权建设。边区参议会于此期间召开，共产党推行精兵简政、减租减息等政策，克服经济困难。", "延安市": "1945年8月抗日战争胜利，中国面临两种命运的选择。中共中央在延安分析战后时局，提出和平、民主、团结的方针，随后毛泽东赴重庆谈判。", "陕西省延安市": "1945年8月抗战胜利后，蒋介石集团在美国支持下加紧准备内战。中共中央在延安揭露国民党挑动内战的行径，同时争取和平民主的实现。", "延安": "1947年春国民党军重点进攻陕甘宁边区，中共中央于3月主动撤离延安，转战陕北。此间人民解放军先后粉碎国民党军的全面进攻和重点进攻，战局开始向有利于人民的方向转变。", "陕北靖边县青阳岔(其一为延安)": "1946年全面内战爆发，1947年3月中共中央决定暂时放弃延安。毛泽东率中央机关转战陕北，靖边县青阳岔是转战陕北途中的重要驻地之一。", "陕北靖边县青阳岔": "1947年中共中央转战陕北期间，青阳岔是中央机关驻地之一。此间西北野战军取得青化砭、羊马河、蟠龙等战役胜利，稳定了西北战局。", "陕北靖边县王家湾": "1947年4月至6月，中共中央和毛泽东在王家湾停留，指挥全国解放战争。此间人民解放军由战略防御逐步转入战略反攻的准备阶段。", "陕北佳县朱官寨": "1947年8月至9月，中共中央转战陕北期间驻于佳县朱官寨一带。此间刘邓大军千里跃进大别山，人民解放军转入全国性战略进攻。", "陕北佳县神泉堡": "1947年秋，中共中央驻于佳县神泉堡，在此发出《中国人民解放军宣言》，提出“打倒蒋介石，解放全中国”的口号。同时公布《中国土地法大纲》，解放区土地改革深入开展。", "陕北佳县（转战陕北期间，佳县神泉堡一带）": "1947年中共中央转战陕北期间驻于佳县一带，指挥全国解放战争并领导解放区土地改革。10月在此重新颁布中国人民解放军三大纪律八项注意。", "陕北米脂县杨家沟": "1947年11月至1948年3月，中共中央驻于米脂县杨家沟，毛泽东在此作《目前形势和我们的任务》报告。此地是转战陕北期间居住时间最长的驻地，召开了十二月会议，制定了一系列纠正土改中“左”倾偏向的政策。", "陕西米脂县杨家沟": "1948年初，中共中央仍驻杨家沟，集中研究土地改革、工商业政策和建立报告制度等问题，为夺取全国胜利进行政策和纪律方面的准备。", "陕北杨家沟": "1948年初中共中央在杨家沟期间，针对新老解放区不同情况制定土地改革的具体政策，纠正工作中的偏差，为新解放区工作提供指导。", "陕北": "1948年初，中共中央转战陕北后期，针对新解放区的情况制定土地改革要点，指导即将大批出现的新解放区的农村工作。1948年3月中共中央东渡黄河离开陕北。", "山西兴县蔡家崖（晋绥解放区首府）": "1948年春，毛泽东率中央机关东渡黄河后途经晋绥解放区，兴县蔡家崖是晋绥解放区领导机关所在地。毛泽东在此召开干部会议，阐明党在新民主主义革命时期总路线和土地改革政策。", "山西兴县蔡家崖（晋绥解放区）": "1948年春，毛泽东在晋绥解放区首府兴县蔡家崖停留期间，对《晋绥日报》编辑人员发表谈话，总结党报工作的经验，强调报纸的宣传和组织作用。", "山西临县双塔村（转战陕北结束后东渡黄河，经晋绥解放区）": "1948年3月，中共中央结束转战陕北，东渡黄河经晋绥解放区前往河北。此间人民解放军攻克洛阳等城市，中央就城市政策作出指示。", "河北阜平县城南庄": "1948年4月，毛泽东率中央机关到达晋察冀军区所在地阜平县城南庄。在此召开中共中央书记处扩大会议，研究如何促进革命形势迅速发展，并筹划南下和解放全中国的战略部署。", "河北西柏坡": "1948年5月至1949年3月，西柏坡是中共中央所在地，党中央在此指挥了辽沈、淮海、平津三大战役，召开了七届二中全会，提出党的工作重心由乡村转移到城市。西柏坡由此被称为“新中国从这里走来”的地方。", "河北平山县西柏坡": "1948年5月起，中共中央驻地设于平山县西柏坡村。党中央在此运筹帷幄，指挥三大战役取得胜利，领导筹备建立新中国，发表《将革命进行到底》等著名文献。", "河北西柏坡（平山县西柏坡村）": "1949年3月，中共七届二中全会在西柏坡召开，规定了党在全国胜利后的基本政策，提出“两个务必”，会后中共中央迁往北平。", "北平": "1949年1月北平和平解放，3月中共中央进驻北平。此间人民解放军渡江南下解放南京，新政治协商会议筹备会召开，毛泽东发表《论人民民主专政》，为中华人民共和国成立作准备。", "北京": "1949年10月1日中华人民共和国成立，北京成为首都。1949-1957年间党和政府在此领导国民经济恢复、抗美援朝、社会主义改造和第一个五年计划建设，1956年基本完成对生产资料私有制的社会主义改造。", "山东青岛": "1957年毛泽东在青岛期间，正值反右派斗争开展之时。他在此修改和撰写关于当时形势的文章，全国人大常委会随后决定整风运动转入反右派斗争。", "苏联莫斯科": "1957年11月，毛泽东率中共代表团赴莫斯科参加十月革命四十周年庆典和各国共产党、工人党代表会议。此间中苏关系尚处友好合作阶段，毛泽东在此期间发表了一系列谈话。"};